import Foundation
import Network
import MetalKit
import AppKit

public class ClientCore {
    public static let shared = ClientCore()

    private let tcpChannel = TCPChannel()
    private let udpChannel = UDPChannel()
    private let frameReceiver = FrameReceiver()
    private let decoder = VideoDecoder()
    private let audioPlayer = ClientAudioPlayer()
    public let isAudioMuted = AtomicBool(false)
    private var renderer: MetalRenderer?
    private var inputSender: InputSender?
    // Protects inputSender from concurrent access between TCP callbacks and UI thread.
    private let stateQueue = DispatchQueue(label: "eclipticrd.client.state")

    private var abrTimer: DispatchSourceTimer?
    private let abrQueue = DispatchQueue(label: "eclipticrd.client.abr")
    private var currentBitrate: Int = ERDConstants.defaultBitrate
    private var lowLossStartTime: Date?

    private var clipboardMonitor: ClipboardMonitor?
    private var peerCapabilities: HandshakeCapabilities = []
    private var nextStreamConfigRequestID: UInt32 = 1
    public var onStreamConfigResponse: (@Sendable (StreamConfigurationResponsePayload) -> Void)?
    public var onStreamConfigRejected: (@Sendable (StreamConfigurationRejectPayload) -> Void)?
    public var onStreamConfigError: (@Sendable (StreamConfigurationErrorPayload) -> Void)?

    public var onSessionReady: (@Sendable () -> Void)?
    public var onServerIdentity: (@Sendable (String) -> Void)?
    public var onDisconnected: (@Sendable () -> Void)?
    public var onError: (@Sendable (String) -> Void)?
    public var onClipboardSynced: (@Sendable (String) -> Void)?

    public var serverHost: String?
    private var udpTargetHost: String?
    private var _serverScreenWidth: Int = 0
    private var _serverScreenHeight: Int = 0
    public var serverScreenWidth: Int {
        get { stateQueue.sync { _serverScreenWidth } }
        set { stateQueue.sync { _serverScreenWidth = newValue } }
    }
    public var serverScreenHeight: Int {
        get { stateQueue.sync { _serverScreenHeight } }
        set { stateQueue.sync { _serverScreenHeight = newValue } }
    }

    private init() {
        // Wire pipeline: UDP → FrameReceiver → VideoDecoder → MetalRenderer
        udpChannel.onReceive = { [weak self] data, endpoint in
            guard let self = self else { return }
            guard data.count >= ERDConstants.packetHeaderSize else { return }

            // Bypass frame assembly queue for zero-jitter, real-time audio playback
            if data[2] == PacketType.audioFrame.rawValue {
                if !self.isAudioMuted.value {
                    let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)
                    self.audioPlayer.play(data: payload)
                }
            } else {
                self.frameReceiver.handlePacket(data)
            }
        }

        frameReceiver.onFrameReady = { [weak self] data, header in
            self?.serverScreenWidth = Int(header.width)
            self?.serverScreenHeight = Int(header.height)
            self?.decoder.decode(data)
        }

        frameReceiver.onCursorUpdate = { [weak self] cursor in
            self?.renderer?.updateCursor(x: cursor.x, y: cursor.y)
        }

        decoder.onDecodedFrame = { [weak self] pixelBuffer in
            self?.renderer?.displayFrame(pixelBuffer)
        }
    }

    // MARK: - Connection Methods

    /// Connect via direct IP (LAN manual)
    public func start(host: String?) {
        guard let host = host else { return }
        self.serverHost = host
        ERDLog.info("[Client] Connecting to \(host)")

        tcpChannel.connect(host: host, port: ERDConstants.tcpPort)
        setupTCPHandlers(host: host)
    }

    /// Connect via Bonjour endpoint
    public func start(endpoint: NWEndpoint, name: String) {
        ERDLog.info("[Client] Connecting to Bonjour Endpoint: \(name)")
        tcpChannel.connect(to: endpoint)
        setupTCPHandlers(host: nil)
    }

    /// Connect via PIN (Internet / NAT traversal)
    public func startICE(pin: String) {
        Task {
            do {
                // 1. Get our public IP via STUN
                let stun = STUNClient()
                let (publicIP, publicPort) = try await stun.fetchPublicIP()
                ERDLog.info("[ClientCore] STUN Public IP: \(publicIP):\(publicPort)")

                // 2. Get local IP
                let localIP = NetworkUtils.getLocalIP() ?? "127.0.0.1"
                let localPort = ERDConstants.tcpPort

                // 3. Exchange candidates via ntfy.sh
                let signaling = SignalingClient(pin: pin, role: "client")
                let ourCandidate = SessionCandidate(role: "client", localIP: localIP, localPort: localPort,
                                                     publicIP: publicIP, publicPort: publicPort)

                ERDLog.info("[ClientCore] Waiting for server candidate via ntfy.sh...")
                let serverCandidate = try await signaling.exchangeCandidate(ourCandidate)
                ERDLog.info("[ClientCore] Retrieved Server Candidate: \(serverCandidate.publicIP):\(serverCandidate.publicPort)")
                signaling.stop()

                // 4. Try ICE: connect to both local and public IP
                var endpoints: [NWEndpoint] = []

                // Local IP endpoint
                if let port = NWEndpoint.Port(rawValue: serverCandidate.localPort) {
                    endpoints.append(.hostPort(host: NWEndpoint.Host(serverCandidate.localIP), port: port))
                }
                // Public IP endpoint
                if let port = NWEndpoint.Port(rawValue: serverCandidate.publicPort) {
                    endpoints.append(.hostPort(host: NWEndpoint.Host(serverCandidate.publicIP), port: port))
                }

                tcpChannel.connectICE(endpoints: endpoints)
                // Pass nil so the onConnect handler resolves host from
                // the actual winning TCP connection (local or public).
                setupTCPHandlers(host: nil)

            } catch {
                ERDLog.error("[ClientCore] ICE connection failed: \(error)")
                self.onError?("ICE connection failed: \(error.localizedDescription)")
            }
        }
    }

    public func stop() {
        stopClipboardSync()
        stopABR()
        stateQueue.sync {
            inputSender?.stopCapturing()
            inputSender = nil
        }
        frameReceiver.stop()
        decoder.stop()
        audioPlayer.stop()
        serverHost = nil
        udpTargetHost = nil
        serverScreenWidth = 0
        serverScreenHeight = 0
        tcpChannel.stop()
        udpChannel.stop()
        ERDLog.info("[Client] Disconnected from server")
    }

    // MARK: - Internal

    private func setupTCPHandlers(host: String?) {
        tcpChannel.onConnect = { [weak self] in
            guard let self = self else { return }

            // Resolve server IP for UDP
            let resolvedHost = host ?? self.tcpChannel.remoteHostIP ?? "127.0.0.1"
            self.serverHost = resolvedHost
            self.udpTargetHost = resolvedHost

            if host == nil {
                ERDLog.info("[Client] Resolved server IP: \(resolvedHost)")
            }

            ERDLog.info("[Client] TCP connected, sending handshake...")
            let hs = HandshakePayload(hostname: ProcessInfo.processInfo.hostName,
                                       screenWidth: 0, screenHeight: 0, scaleFactor: 1.0,
                                       capabilities: [.streamConfiguration, .textClipboardSync])
            let header = PacketHeader(type: .handshake, sequence: 0, timestamp: 0)
            var packet = header.serialize()
            packet.append(hs.serialize())
            self.tcpChannel.send(packet)
        }

        tcpChannel.onReceive = { [weak self] data in
            guard let self = self else { return }
            guard data.count >= ERDConstants.packetHeaderSize else {
                return
            }
            guard let header = PacketHeader.deserialize(from: data) else {
                return
            }
            let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

            if header.type == .handshakeAck {
                if let hs = HandshakePayload.deserialize(from: payload) {
                    ERDLog.info("[Client] Server: \(hs.hostname) \(hs.screenWidth)x\(hs.screenHeight) caps=\(hs.capabilities.rawValue)")
                    self.onServerIdentity?(hs.hostname)
                    self.serverScreenWidth = Int(hs.screenWidth)
                    self.serverScreenHeight = Int(hs.screenHeight)
                    self.stateQueue.sync { self.peerCapabilities = hs.capabilities }

                    let udpHost = self.udpTargetHost ?? self.serverHost ?? "127.0.0.1"
                    self.udpChannel.onReady = { [weak self] in
                        self?.udpChannel.sendPing()
                    }
                    self.udpChannel.connect(host: udpHost, port: ERDConstants.udpPort)
                    ERDLog.info("[Client] Connecting UDP to \(udpHost):\(ERDConstants.udpPort)")
                    self.startABR()
                    self.startClipboardSync()
                    self.audioPlayer.start()
                    self.onSessionReady?()
                }
            } else if header.type == .control {
                if let msg = ControlMessage.deserialize(from: payload) {
                    switch msg.type {
                    case .ping:
                        self.tcpChannel.sendControl(ControlMessage(type: .pong))
                    case .streamConfigResponse:
                        if let data = msg.payload,
                           let resp = StreamConfigurationResponsePayload.deserialize(from: data) {
                            ERDLog.info("[Client] Stream config accepted: \(resp.activeConfiguration.width)x\(resp.activeConfiguration.height)")
                            self.onStreamConfigResponse?(resp)
                        }
                    case .streamConfigReject:
                        if let data = msg.payload,
                           let reject = StreamConfigurationRejectPayload.deserialize(from: data) {
                            ERDLog.warning("[Client] Stream config rejected: \(reject.message)")
                            self.onStreamConfigRejected?(reject)
                        }
                    case .streamConfigError:
                        if let data = msg.payload,
                           let err = StreamConfigurationErrorPayload.deserialize(from: data) {
                            ERDLog.error("[Client] Stream config error: \(err.message)")
                            self.onStreamConfigError?(err)
                        }
                    case .clipboardSyncUpdate:
                        if let data = msg.payload,
                           let update = ClipboardSyncUpdatePayload.deserialize(from: data) {
                            self.handleClipboardUpdate(update)
                        }
                    case .clipboardSyncError:
                        if let data = msg.payload,
                           let err = ClipboardSyncErrorPayload.deserialize(from: data) {
                            ERDLog.warning("[Client] Clipboard sync error: \(err.message)")
                        }
                    default: break
                    }
                }
            }
        }

        tcpChannel.onDisconnect = { [weak self] in
            ERDLog.info("[Client] Disconnected from server")
            self?.onDisconnected?()
            self?.stop()
        }
    }

    public func setupRenderer(mtkView: MTKView) {
        renderer = MetalRenderer(mtkView: mtkView)
    }

    public func startInput(in view: NSView) {
        let sender = InputSender(tcpChannel: tcpChannel)
        sender.startCapturing(in: view)
        stateQueue.sync { inputSender = sender }
    }

    // MARK: - Stream Configuration

    public func requestStreamConfiguration(_ config: StreamConfiguration) {
        let requestID = stateQueue.sync { () -> UInt32 in
            let id = nextStreamConfigRequestID
            nextStreamConfigRequestID += 1
            return id
        }
        let request = StreamConfigurationRequestPayload(requestID: requestID, desiredConfiguration: config)
        let msg = ControlMessage(type: .streamConfigRequest, payload: request.serialize())
        tcpChannel.sendControl(msg)
        ERDLog.info("[Client] Requesting stream config: \(config.width)x\(config.height) @\(config.framesPerSecond)fps")
    }

    // MARK: - Clipboard Sync

    private func startClipboardSync() {
        let peerCaps = stateQueue.sync { self.peerCapabilities }
        guard peerCaps.contains(.textClipboardSync) else {
            ERDLog.info("[Client] Server does not support clipboard sync, skipping")
            return
        }

        let monitor = ClipboardMonitor { [weak self] text in
            guard let self = self else { return }
            let update = ClipboardSyncUpdatePayload(
                requestID: 0,
                direction: .clientToHost,
                origin: .localPasteboard,
                text: text)
            if let data = update.serialize() {
                let msg = ControlMessage(type: .clipboardSyncUpdate, payload: data)
                self.tcpChannel.sendControl(msg)
            }
        }
        stateQueue.sync { self.clipboardMonitor = monitor }
        monitor.start()
        ERDLog.info("[Client] Clipboard sync started")
    }

    private func stopClipboardSync() {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.stop()
        stateQueue.sync { self.clipboardMonitor = nil }
    }

    private func handleClipboardUpdate(_ update: ClipboardSyncUpdatePayload) {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.applyRemoteText(update.text)
        ERDLog.info("[Client] Clipboard received from server (\(update.text.count) chars)")
        onClipboardSynced?(update.text)
    }

    // MARK: - Adaptive Bitrate

    private func startABR() {
        stopABR()
        currentBitrate = ERDConstants.defaultBitrate
        lowLossStartTime = nil

        let timer = DispatchSource.makeTimerSource(queue: abrQueue)
        timer.schedule(deadline: .now() + 3.0, repeating: 3.0)
        timer.setEventHandler { [weak self] in
            self?.evaluateBitrate()
        }
        timer.resume()
        abrTimer = timer
    }

    private func stopABR() {
        abrTimer?.cancel()
        abrTimer = nil
    }

    private func evaluateBitrate() {
        let lossRatio = frameReceiver.frameLossRatio
        var newBitrate = currentBitrate

        if lossRatio > 0.10 {
            lowLossStartTime = nil
            newBitrate = max(ERDConstants.minBitrate, Int(Double(currentBitrate) * 0.75))
            ERDLog.info("[Client] ABR: loss \(String(format: "%.1f", lossRatio * 100))%% → reduce to \(newBitrate)")
        } else if lossRatio < 0.02 {
            if let start = lowLossStartTime {
                if Date().timeIntervalSince(start) >= 10.0 {
                    newBitrate = min(ERDConstants.maxBitrate, Int(Double(currentBitrate) * 1.10))
                    lowLossStartTime = Date()
                    ERDLog.info("[Client] ABR: stable → increase to \(newBitrate)")
                }
            } else {
                lowLossStartTime = Date()
            }
        } else {
            lowLossStartTime = nil
        }

        if newBitrate != currentBitrate {
            currentBitrate = newBitrate
            let payload = BitrateAdjustPayload(targetBitrate: Int32(newBitrate))
            let msg = ControlMessage(type: .bitrateAdjust, payload: payload.serialize())
            tcpChannel.sendControl(msg)
        }
    }

    public struct StreamStats {
        public let fps: Double
        public let bitrate: Int
        public let frameLoss: Double
        public let framesReceived: Int
    }

    public func getStats() -> StreamStats {
        StreamStats(
            fps: frameReceiver.recentFPS,
            bitrate: currentBitrate,
            frameLoss: frameReceiver.frameLossRatio,
            framesReceived: frameReceiver.totalFramesReceived
        )
    }
}

import Foundation
import MetalKit
import CoreVideo

public class MetalRenderer: NSObject, MTKViewDelegate {
    public var mtkView: MTKView?
    private var device: MTLDevice?
    private var commandQueue: MTLCommandQueue?
    private var pipelineState: MTLRenderPipelineState?
    private var cursorPipelineState: MTLRenderPipelineState?
    private var textureCache: CVMetalTextureCache?
    private var currentTexture: MTLTexture?
    private var cursorTexture: MTLTexture?
    private var vertexBuffer: MTLBuffer?
    private let textureLock = NSLock()
    private let cursorLock = NSLock()
    private var cursorX: Float = 0
    private var cursorY: Float = 0

    private struct CursorUniforms {
        var position: SIMD2<Float>
        var size: SIMD2<Float>
    }

    public override init() { super.init() }

    public init?(mtkView: MTKView) {
        super.init()
        guard let device = mtkView.device ?? MTLCreateSystemDefaultDevice() else { return nil }
        self.device = device
        self.mtkView = mtkView
        mtkView.device = device
        mtkView.delegate = self
        mtkView.framebufferOnly = false
        mtkView.colorPixelFormat = .bgra8Unorm

        commandQueue = device.makeCommandQueue()

        // Create texture cache
        var cache: CVMetalTextureCache?
        CVMetalTextureCacheCreate(kCFAllocatorDefault, nil, device, nil, &cache)
        textureCache = cache

        // Create vertex buffer (full-screen quad for video rendering)
        let vertices: [Float] = [
            -1, -1, 0, 1,   // bottom-left  (pos.xy, tex.xy)
             1, -1, 1, 1,   // bottom-right
            -1,  1, 0, 0,   // top-left
             1,  1, 1, 0,   // top-right
        ]
        vertexBuffer = device.makeBuffer(bytes: vertices, length: vertices.count * MemoryLayout<Float>.size, options: .storageModeShared)

        // Generate programmatic mouse cursor texture
        setupCursorTexture()

        // Create pipelines
        setupPipeline()
    }

    private func setupCursorTexture() {
        guard let device = device else { return }

        let width = 32
        let height = 32
        var pixels = [UInt32](repeating: 0, count: width * height)

        // Classic Mac pointer arrow pattern: 'B' = black border, 'W' = white fill, '.' = transparent
        let pattern: [String] = [
            "B",
            "BB",
            "BWB",
            "BWWB",
            "BWWWB",
            "BWWWWB",
            "BWWWWWB",
            "BWWWWWWB",
            "BWWWWWWWB",
            "BWWWWWWWWB",
            "BWWWWWWWWWB",
            "BWWWWWWWWWWB",
            "BWWWWWWWWWWWB",
            "BWWWWWWWWWWWWB",
            "BWWWWWWWWWWWWWB",
            "BWWWWWWBBBBBBBBB",
            "BWWWWWB",
            "BWWBWWB",
            "BWB.BWB",
            "B...BWB",
            "....BWB",
            ".....B"
        ]

        for y in 0..<height {
            for x in 0..<width {
                var color: UInt32 = 0x00000000 // transparent
                if y < pattern.count {
                    let row = pattern[y]
                    if x < row.count {
                        let char = row[row.index(row.startIndex, offsetBy: x)]
                        if char == "B" {
                            color = 0xFF000000 // Black border (alpha 0xFF, BGRA order)
                        } else if char == "W" {
                            color = 0xFFFFFFFF // White fill (alpha 0xFF, BGRA order)
                        }
                    }
                }
                pixels[y * width + x] = color
            }
        }

        let descriptor = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: .bgra8Unorm, width: width, height: height, mipmapped: false)
        descriptor.usage = .shaderRead
        cursorTexture = device.makeTexture(descriptor: descriptor)

        let region = MTLRegionMake2D(0, 0, width, height)
        cursorTexture?.replace(region: region, mipmapLevel: 0, withBytes: pixels, bytesPerRow: width * 4)
    }

    private func setupPipeline() {
        guard let device = device else { return }

        // Shader source embedding as a CLI fallback in case the Default Library isn't bundled (e.g. TestCLI runner)
        let shaderSource = """
        #include <metal_stdlib>
        using namespace metal;
        struct VertexOut {
            float4 position [[position]];
            float2 texCoord;
        };
        vertex VertexOut videoVertex(uint vid [[vertex_id]], constant float4 *vertices [[buffer(0)]]) {
            VertexOut out;
            out.position = float4(vertices[vid].xy, 0, 1);
            out.texCoord = vertices[vid].zw;
            return out;
        }
        fragment half4 videoFragment(VertexOut in [[stage_in]], texture2d<half> tex [[texture(0)]]) {
            constexpr sampler s(mag_filter::linear, min_filter::linear);
            return tex.sample(s, in.texCoord);
        }
        struct CursorUniforms {
            float2 position;
            float2 size;
        };
        vertex VertexOut cursorVertex(uint vid [[vertex_id]], constant CursorUniforms &uniforms [[buffer(0)]]) {
            float2 ndcPos = float2(uniforms.position.x * 2.0 - 1.0, (1.0 - uniforms.position.y) * 2.0 - 1.0);
            float2 ndcSize = uniforms.size;
            float2 positions[4] = {
                float2(ndcPos.x, ndcPos.y),
                float2(ndcPos.x + ndcSize.x, ndcPos.y),
                float2(ndcPos.x, ndcPos.y - ndcSize.y),
                float2(ndcPos.x + ndcSize.x, ndcPos.y - ndcSize.y)
            };
            float2 texCoords[4] = {
                float2(0.0, 0.0),
                float2(1.0, 0.0),
                float2(0.0, 1.0),
                float2(1.0, 1.0)
            };
            VertexOut out;
            out.position = float4(positions[vid], 0, 1);
            out.texCoord = texCoords[vid];
            return out;
        }
        fragment half4 cursorFragment(VertexOut in [[stage_in]], texture2d<half> tex [[texture(0)]]) {
            constexpr sampler s(mag_filter::linear, min_filter::linear);
            half4 color = tex.sample(s, in.texCoord);
            if (color.a < 0.05) { discard_fragment(); }
            return color;
        }
        """

        do {
            // 1. Try to load precompiled shaders from bundle's default library (Precompilation)
            // 2. Fallback to CLI JIT compilation to guarantee TestCLI and E2ETests continue passing
            let library: MTLLibrary
            if let defaultLibrary = device.makeDefaultLibrary() {
                library = defaultLibrary
                ERDLog.info("[MetalRenderer] Loaded precompiled shaders from .metallib!")
            } else {
                library = try device.makeLibrary(source: shaderSource, options: nil)
                ERDLog.info("[MetalRenderer] Falling back to dynamic shader JIT compilation")
            }

            // Create Video Pipeline State
            let videoDescriptor = MTLRenderPipelineDescriptor()
            videoDescriptor.vertexFunction = library.makeFunction(name: "videoVertex")
            videoDescriptor.fragmentFunction = library.makeFunction(name: "videoFragment")
            videoDescriptor.colorAttachments[0].pixelFormat = .bgra8Unorm
            pipelineState = try device.makeRenderPipelineState(descriptor: videoDescriptor)

            // Create Cursor Pipeline State (with Alpha Blending enabled)
            let cursorDescriptor = MTLRenderPipelineDescriptor()
            cursorDescriptor.vertexFunction = library.makeFunction(name: "cursorVertex")
            cursorDescriptor.fragmentFunction = library.makeFunction(name: "cursorFragment")
            cursorDescriptor.colorAttachments[0].pixelFormat = .bgra8Unorm
            cursorDescriptor.colorAttachments[0].isBlendingEnabled = true
            cursorDescriptor.colorAttachments[0].rgbBlendOperation = .add
            cursorDescriptor.colorAttachments[0].alphaBlendOperation = .add
            cursorDescriptor.colorAttachments[0].sourceRGBBlendFactor = .sourceAlpha
            cursorDescriptor.colorAttachments[0].sourceAlphaBlendFactor = .sourceAlpha
            cursorDescriptor.colorAttachments[0].destinationRGBBlendFactor = .oneMinusSourceAlpha
            cursorDescriptor.colorAttachments[0].destinationAlphaBlendFactor = .oneMinusSourceAlpha
            cursorPipelineState = try device.makeRenderPipelineState(descriptor: cursorDescriptor)

        } catch {
            ERDLog.error("[MetalRenderer] Pipeline creation error: \(error)")
        }
    }

    public func displayFrame(_ pixelBuffer: CVPixelBuffer) {
        guard let cache = textureCache, let _ = device else { return }

        let width = CVPixelBufferGetWidth(pixelBuffer)
        let height = CVPixelBufferGetHeight(pixelBuffer)

        var cvTexture: CVMetalTexture?
        CVMetalTextureCacheCreateTextureFromImage(kCFAllocatorDefault, cache, pixelBuffer, nil, .bgra8Unorm, width, height, 0, &cvTexture)

        guard let cvTex = cvTexture, let texture = CVMetalTextureGetTexture(cvTex) else { return }

        textureLock.lock()
        currentTexture = texture
        textureLock.unlock()
    }

    public func updateCursor(x: Float, y: Float) {
        cursorLock.lock()
        cursorX = x
        cursorY = y
        cursorLock.unlock()
    }

    // MARK: - MTKViewDelegate

    public func draw(in view: MTKView) {
        textureLock.lock()
        let texture = currentTexture
        textureLock.unlock()

        guard let texture = texture,
              let pipeline = pipelineState,
              let commandBuffer = commandQueue?.makeCommandBuffer(),
              let renderPassDescriptor = view.currentRenderPassDescriptor,
              let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: renderPassDescriptor) else {
            return
        }

        // Draw video frame
        encoder.setRenderPipelineState(pipeline)
        encoder.setVertexBuffer(vertexBuffer, offset: 0, index: 0)
        encoder.setFragmentTexture(texture, index: 0)
        encoder.drawPrimitives(type: .triangleStrip, vertexStart: 0, vertexCount: 4)

        // Draw mouse cursor overlay
        cursorLock.lock()
        let cx = cursorX
        let cy = cursorY
        cursorLock.unlock()

        if let cTexture = cursorTexture, let cPipeline = cursorPipelineState, cx >= 0.0 && cx <= 1.0 && cy >= 0.0 && cy <= 1.0 {
            let viewWidth = Float(view.drawableSize.width)
            let viewHeight = Float(view.drawableSize.height)

            if viewWidth > 0 && viewHeight > 0 {
                // Keep the cursor size constant (exactly 32x32 screen pixels) regardless of resolution
                let ndcWidth = (32.0 / viewWidth) * 2.0
                let ndcHeight = (32.0 / viewHeight) * 2.0

                var uniforms = CursorUniforms(
                    position: SIMD2<Float>(cx, cy),
                    size: SIMD2<Float>(ndcWidth, ndcHeight)
                )

                encoder.setRenderPipelineState(cPipeline)
                encoder.setVertexBytes(&uniforms, length: MemoryLayout<CursorUniforms>.size, index: 0)
                encoder.setFragmentTexture(cTexture, index: 0)
                encoder.drawPrimitives(type: .triangleStrip, vertexStart: 0, vertexCount: 4)
            }
        }

        encoder.endEncoding()

        if let drawable = view.currentDrawable {
            commandBuffer.present(drawable)
        }
        commandBuffer.commit()
    }

    public func mtkView(_ view: MTKView, drawableSizeWillChange size: CGSize) {}
}

import Foundation
import VideoToolbox
import CoreMedia

public class VideoDecoder {
    private var session: VTDecompressionSession?
    private var formatDescription: CMVideoFormatDescription?
    private let decoderQueue = DispatchQueue(label: "eclipticrd.decoder", qos: .userInteractive)
    private var retainedSelf: Unmanaged<VideoDecoder>?

    private var sps: Data?
    private var pps: Data?
    private var vps: Data?

    public var onDecodedFrame: ((CVPixelBuffer) -> Void)?

    public init() {}

    // NOTE: Do not call stop() from deinit — decoderQueue.sync would deadlock
    // if the last reference is released on decoderQueue itself.
    // Callers must call stop() explicitly before releasing.

    public func decode(_ data: Data) {
        decoderQueue.async { [weak self] in
            guard let self = self else { return }
            self.processNALUs(data)
        }
    }

    public func stop() {
        decoderQueue.sync {
            if let session = self.session {
                VTDecompressionSessionInvalidate(session)
                self.session = nil
            }
            self.retainedSelf?.release()
            self.retainedSelf = nil
            self.formatDescription = nil
            self.sps = nil; self.pps = nil; self.vps = nil
        }
    }

    private func processNALUs(_ data: Data) {
        // HEVC NALUs use 4-byte length prefix (AVCC format from VideoToolbox output)
        var offset = 0
        while offset + 4 <= data.count {
            let naluLength = data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self).bigEndian }
            offset += 4
            guard naluLength > 0, offset + Int(naluLength) <= data.count else { break }

            let nalu = data.subdata(in: offset..<offset+Int(naluLength))
            let naluType = (nalu[0] >> 1) & 0x3F // HEVC NAL unit type

            switch naluType {
            case 32: // VPS
                vps = nalu
            case 33: // SPS
                sps = nalu
            case 34: // PPS
                pps = nalu
                createDecoderIfNeeded()
            default:
                // IDR (19, 20) or non-IDR (0, 1) - decode it
                if naluType <= 31 || naluType == 19 || naluType == 20 {
                    decodeNALU(nalu)
                }
            }
            offset += Int(naluLength)
        }
    }

    private func createDecoderIfNeeded() {
        guard let vps = vps, let sps = sps, let pps = pps else { return }

        // Nest withUnsafeBytes calls to keep pointers valid for the entire scope.
        var newFormat: CMVideoFormatDescription?
        vps.withUnsafeBytes { vpsBuffer in
            sps.withUnsafeBytes { spsBuffer in
                pps.withUnsafeBytes { ppsBuffer in
                    let pointers: [UnsafePointer<UInt8>] = [
                        vpsBuffer.baseAddress!.assumingMemoryBound(to: UInt8.self),
                        spsBuffer.baseAddress!.assumingMemoryBound(to: UInt8.self),
                        ppsBuffer.baseAddress!.assumingMemoryBound(to: UInt8.self)
                    ]
                    let sizes = [vps.count, sps.count, pps.count]

                    CMVideoFormatDescriptionCreateFromHEVCParameterSets(
                        allocator: kCFAllocatorDefault,
                        parameterSetCount: 3,
                        parameterSetPointers: pointers,
                        parameterSetSizes: sizes,
                        nalUnitHeaderLength: 4,
                        extensions: nil,
                        formatDescriptionOut: &newFormat
                    )
                }
            }
        }

        guard let format = newFormat else { return }

        if session != nil {
            VTDecompressionSessionInvalidate(session!)
            session = nil
        }
        retainedSelf?.release()
        retainedSelf = Unmanaged.passRetained(self)
        formatDescription = format

        let pixelBufferAttributes: [String: Any] = [
            kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_32BGRA,
            kCVPixelBufferMetalCompatibilityKey as String: true
        ]

        var callbackRecord = VTDecompressionOutputCallbackRecord(
            decompressionOutputCallback: decoderCallback,
            decompressionOutputRefCon: retainedSelf!.toOpaque()
        )

        VTDecompressionSessionCreate(
            allocator: kCFAllocatorDefault,
            formatDescription: format,
            decoderSpecification: nil,
            imageBufferAttributes: pixelBufferAttributes as CFDictionary,
            outputCallback: &callbackRecord,
            decompressionSessionOut: &session
        )
    }

    private func decodeNALU(_ nalu: Data) {
        guard let session = session, let format = formatDescription else { return }

        // Wrap NALU with 4-byte length prefix
        var length = UInt32(nalu.count).bigEndian
        var blockData = Data(bytes: &length, count: 4)
        blockData.append(nalu)

        var blockBuffer: CMBlockBuffer?
        let totalLength = blockData.count

        blockData.withUnsafeBytes { rawBuffer in
            guard let baseAddress = rawBuffer.baseAddress else { return }
            CMBlockBufferCreateWithMemoryBlock(
                allocator: kCFAllocatorDefault,
                memoryBlock: nil, blockLength: totalLength,
                blockAllocator: nil, customBlockSource: nil,
                offsetToData: 0, dataLength: totalLength,
                flags: 0, blockBufferOut: &blockBuffer)

            if let block = blockBuffer {
                CMBlockBufferReplaceDataBytes(with: baseAddress, blockBuffer: block, offsetIntoDestination: 0, dataLength: totalLength)
            }
        }

        guard let block = blockBuffer else { return }

        var sampleBuffer: CMSampleBuffer?
        var sizeArray = [totalLength]
        CMSampleBufferCreateReady(
            allocator: kCFAllocatorDefault,
            dataBuffer: block, formatDescription: format,
            sampleCount: 1, sampleTimingEntryCount: 0, sampleTimingArray: nil,
            sampleSizeEntryCount: 1, sampleSizeArray: &sizeArray,
            sampleBufferOut: &sampleBuffer)

        guard let buffer = sampleBuffer else { return }

        var flagsOut = VTDecodeInfoFlags()
        VTDecompressionSessionDecodeFrame(session, sampleBuffer: buffer, flags: [], frameRefcon: nil, infoFlagsOut: &flagsOut)
    }

    fileprivate func frameDecoded(_ imageBuffer: CVImageBuffer) {
        onDecodedFrame?(imageBuffer)
    }
}

private func decoderCallback(decompressionOutputRefCon: UnsafeMutableRawPointer?,
                              sourceFrameRefCon: UnsafeMutableRawPointer?,
                              status: OSStatus,
                              infoFlags: VTDecodeInfoFlags,
                              imageBuffer: CVImageBuffer?,
                              presentationTimeStamp: CMTime,
                              presentationDuration: CMTime) {
    guard status == noErr, let buffer = imageBuffer, let refcon = decompressionOutputRefCon else { return }
    let decoder = Unmanaged<VideoDecoder>.fromOpaque(refcon).takeUnretainedValue()
    decoder.frameDecoded(buffer)
}

import Foundation

public class FrameReceiver {
    private struct FrameAssembly {
        let header: FrameHeaderPayload
        var chunks: [UInt16: Data]
        let startTime: Date

        var isComplete: Bool { chunks.count == Int(header.totalChunks) }

        func assemble() -> Data? {
            guard isComplete else { return nil }
            var result = Data(capacity: Int(header.totalSize))
            for i in 0..<header.totalChunks {
                guard let chunk = chunks[i] else { return nil }
                result.append(chunk)
            }
            return result
        }
    }

    private struct LossEntry {
        let timestamp: Date
        let lost: Int
        let total: Int
    }

    private var frames: [UInt32: FrameAssembly] = [:]
    private let assemblyQueue = DispatchQueue(label: "eclipticrd.frame-assembly", qos: .userInteractive)
    private var cleanupTimer: DispatchSourceTimer?
    private let timeout: Double = ERDConstants.frameAssemblyTimeout

    private var expectedFrameId: UInt32 = 0
    private var hasReceivedFirstFrame = false
    private var lossEntries: [LossEntry] = []
    private let lossLock = NSLock()

    private var completedFrameTimestamps: [Date] = []
    public private(set) var totalFramesReceived: Int = 0

    public var onFrameReady: ((Data, FrameHeaderPayload) -> Void)?
    public var onCursorUpdate: ((CursorUpdate) -> Void)?

    /// Computed property: FPS based on frames completed in the last 1 second
    public var recentFPS: Double {
        assemblyQueue.sync {
            let cutoff = Date().addingTimeInterval(-1.0)
            let recentCount = completedFrameTimestamps.filter { $0 > cutoff }.count
            return Double(recentCount)
        }
    }

    public var frameLossRatio: Double {
        lossLock.lock()
        defer { lossLock.unlock() }
        let cutoff = Date().addingTimeInterval(-5.0)
        let recent = lossEntries.filter { $0.timestamp > cutoff }
        let totalLost = recent.reduce(0) { $0 + $1.lost }
        let totalFrames = recent.reduce(0) { $0 + $1.total }
        guard totalFrames > 0 else { return 0.0 }
        return Double(totalLost) / Double(totalFrames)
    }

    public init() {
        startCleanupTimer()
    }

    deinit {
        let timer = cleanupTimer
        assemblyQueue.async {
            timer?.cancel()
        }
    }

    public func stop() {
        assemblyQueue.sync {
            self.cleanupTimer?.cancel()
            self.cleanupTimer = nil
            self.frames.removeAll()
            self.completedFrameTimestamps.removeAll()
            self.totalFramesReceived = 0
            self.expectedFrameId = 0
            self.startCleanupTimer()
        }
        lossLock.lock()
        lossEntries.removeAll()
        hasReceivedFirstFrame = false
        lossLock.unlock()
    }

    public func handlePacket(_ data: Data) {
        guard data.count >= ERDConstants.packetHeaderSize else { return }
        guard let header = PacketHeader.deserialize(from: data) else { return }
        let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

        assemblyQueue.async { [weak self] in
            switch header.type {
            case .frameHeader:
                self?.handleFrameHeader(payload)
            case .frameChunk:
                self?.handleFrameChunk(payload)
            case .cursorUpdate:
                if let cursor = CursorUpdate.deserialize(from: payload) {
                    self?.onCursorUpdate?(cursor)
                }
            default: break
            }
        }
    }

    private func handleFrameHeader(_ data: Data) {
        guard let fh = FrameHeaderPayload.deserialize(from: data) else {
            ERDLog.error("[FrameReceiver] Failed to deserialize frame header from \(data.count) bytes")
            return
        }

        if fh.isKeyFrame {
            let keysToRemove = frames.keys.filter { $0 < fh.frameId }
            for key in keysToRemove {
                if let assembly = frames[key], !assembly.isComplete {
                    frames.removeValue(forKey: key)
                }
            }
        }

        trackFrameLoss(receivedFrameId: fh.frameId)
        frames[fh.frameId] = FrameAssembly(header: fh, chunks: [:], startTime: Date())
    }

    private func handleFrameChunk(_ data: Data) {
        guard let chunk = FrameChunkPayload.deserialize(from: data) else {
            ERDLog.error("[FrameReceiver] Failed to deserialize chunk from \(data.count) bytes")
            return
        }
        guard frames[chunk.frameId] != nil else {
            ERDLog.debug("[FrameReceiver] Orphan chunk: frame#\(chunk.frameId) idx=\(chunk.chunkIndex) (no header yet)")
            return
        }

        frames[chunk.frameId]!.chunks[chunk.chunkIndex] = chunk.chunkData
        let assembly = frames[chunk.frameId]!

        if assembly.isComplete {
            let completed = frames.removeValue(forKey: chunk.frameId)!
            if let frameData = completed.assemble() {
                ERDLog.video("[FrameReceiver] ✅ Frame #\(chunk.frameId) assembled: \(frameData.count) bytes")
                totalFramesReceived += 1
                completedFrameTimestamps.append(Date())
                let cutoff = Date().addingTimeInterval(-2.0)
                completedFrameTimestamps.removeAll { $0 < cutoff }
                onFrameReady?(frameData, completed.header)
            }
        }
    }

    private func trackFrameLoss(receivedFrameId: UInt32) {
        lossLock.lock()
        defer { lossLock.unlock() }

        if !hasReceivedFirstFrame {
            hasReceivedFirstFrame = true
            expectedFrameId = receivedFrameId + 1
            lossEntries.append(LossEntry(timestamp: Date(), lost: 0, total: 1))
            return
        }

        let gap = receivedFrameId > expectedFrameId ? Int(receivedFrameId - expectedFrameId) : 0
        lossEntries.append(LossEntry(timestamp: Date(), lost: gap, total: 1 + gap))
        expectedFrameId = receivedFrameId + 1

        let cutoff = Date().addingTimeInterval(-10.0)
        lossEntries.removeAll { $0.timestamp < cutoff }
    }

    private func startCleanupTimer() {
        let timer = DispatchSource.makeTimerSource(queue: assemblyQueue)
        timer.schedule(deadline: .now() + 1.0, repeating: 1.0)
        timer.setEventHandler { [weak self] in
            guard let self = self else { return }
            let now = Date()
            self.frames = self.frames.filter { now.timeIntervalSince($0.value.startTime) < self.timeout }
        }
        timer.resume()
        cleanupTimer = timer
    }
}

import AppKit

public class InputSender {
    private let tcpChannel: TCPChannel
    private var captureView: NSView?
    private var localMonitor: Any?

    public init(tcpChannel: TCPChannel) {
        self.tcpChannel = tcpChannel
    }

    deinit { stopCapturing() }

    public func startCapturing(in view: NSView) {
        self.captureView = view

        let eventMask: NSEvent.EventTypeMask = [
            .mouseMoved, .leftMouseDown, .leftMouseUp, .rightMouseDown, .rightMouseUp,
            .leftMouseDragged, .rightMouseDragged, .scrollWheel,
            .keyDown, .keyUp, .flagsChanged
        ]

        localMonitor = NSEvent.addLocalMonitorForEvents(matching: eventMask) { [weak self] event in
            self?.handleEvent(event)
            return event
        }
    }

    public func stopCapturing() {
        if let m = localMonitor { NSEvent.removeMonitor(m); localMonitor = nil }
        captureView = nil
    }

    private func handleEvent(_ event: NSEvent) {
        guard let view = captureView else { return }

        let location = view.convert(event.locationInWindow, from: nil)
        let bounds = view.bounds
        guard bounds.width > 0, bounds.height > 0 else { return }

        let normX = Float(max(0, min(1, location.x / bounds.width)))
        let normY = Float(max(0, min(1, 1.0 - (location.y / bounds.height)))) // Flip Y

        var inputType: InputEventType
        var keyCode: UInt16 = 0
        var scrollDX: Float = 0
        var scrollDY: Float = 0

        switch event.type {
        case .mouseMoved:       inputType = .mouseMove
        case .leftMouseDown:    inputType = .leftMouseDown
        case .leftMouseUp:      inputType = .leftMouseUp
        case .rightMouseDown:   inputType = .rightMouseDown
        case .rightMouseUp:     inputType = .rightMouseUp
        case .leftMouseDragged: inputType = .leftMouseDragged
        case .rightMouseDragged: inputType = .rightMouseDragged
        case .scrollWheel:
            inputType = .scrollWheel
            scrollDX = Float(event.scrollingDeltaX)
            scrollDY = Float(event.scrollingDeltaY)
        case .keyDown:
            inputType = .keyDown
            keyCode = event.keyCode
        case .keyUp:
            inputType = .keyUp
            keyCode = event.keyCode
        case .flagsChanged:
            inputType = .flagsChanged
            keyCode = event.keyCode
        default: return
        }

        // Map NSEvent modifier flags
        var modifiers = ModifierFlags()
        if event.modifierFlags.contains(.shift)   { modifiers.insert(.shift) }
        if event.modifierFlags.contains(.control) { modifiers.insert(.control) }
        if event.modifierFlags.contains(.option)  { modifiers.insert(.option) }
        if event.modifierFlags.contains(.command) { modifiers.insert(.command) }
        if event.modifierFlags.contains(.capsLock) { modifiers.insert(.capsLock) }

        let payload = InputEventPayload(type: inputType, x: normX, y: normY, keyCode: keyCode,
                                         modifiers: modifiers, scrollDeltaX: scrollDX, scrollDeltaY: scrollDY)
        tcpChannel.sendInput(payload)
    }
}

import Foundation
import AudioToolbox

public class ClientAudioPlayer {
    private var queue: AudioQueueRef?
    private let queueAccessQueue = DispatchQueue(label: "eclipticrd.audioplayer")
    private var isRunning = false
    private let format: AudioStreamBasicDescription

    public init() {
        // Configure ASBD for ScreenCaptureKit standard: 48kHz Stereo Float32 Interleaved
        var asbd = AudioStreamBasicDescription()
        asbd.mSampleRate = 48000.0
        asbd.mFormatID = kAudioFormatLinearPCM
        asbd.mFormatFlags = kAudioFormatFlagIsFloat | kAudioFormatFlagIsPacked
        asbd.mBytesPerPacket = 8 // 4 bytes (Float32) * 2 channels
        asbd.mFramesPerPacket = 1
        asbd.mBytesPerFrame = 8
        asbd.mChannelsPerFrame = 2
        asbd.mBitsPerChannel = 32
        self.format = asbd
    }

    deinit {
        stop()
    }

    public func start() {
        queueAccessQueue.sync {
            guard !isRunning else { return }

            var tempQueue: AudioQueueRef?
            var fmt = format
            // Create a low-latency playback output queue
            let status = AudioQueueNewOutput(&fmt, { _, _, _ in }, nil, nil, nil, 0, &tempQueue)

            guard status == noErr, let q = tempQueue else {
                ERDLog.error("[AudioPlayer] Failed to create AudioQueue: \(status)")
                return
            }

            self.queue = q
            AudioQueueStart(q, nil)
            self.isRunning = true
            ERDLog.info("[AudioPlayer] Started AudioQueue playback")
        }
    }

    public func stop() {
        queueAccessQueue.sync {
            guard isRunning, let q = queue else { return }
            AudioQueueStop(q, true)
            AudioQueueDispose(q, true)
            self.queue = nil
            self.isRunning = false
            ERDLog.info("[AudioPlayer] Stopped AudioQueue playback")
        }
    }

    public func play(data: Data) {
        queueAccessQueue.async { [weak self] in
            guard let self = self, self.isRunning, let q = self.queue else { return }

            var buffer: AudioQueueBufferRef?
            let status = AudioQueueAllocateBuffer(q, UInt32(data.count), &buffer)

            guard status == noErr, let buf = buffer else { return }

            // Copy audio payload into native buffer
            data.withUnsafeBytes { rawBuffer in
                if let baseAddress = rawBuffer.baseAddress {
                    memcpy(buf.pointee.mAudioData, baseAddress, data.count)
                }
            }
            buf.pointee.mAudioDataByteSize = UInt32(data.count)

            // Enqueue buffer for immediate zero-latency audio playback
            AudioQueueEnqueueBuffer(q, buf, 0, nil)
        }
    }
}

#include <metal_stdlib>
using namespace metal;

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

// 1. Video Shaders
vertex VertexOut videoVertex(uint vid [[vertex_id]], constant float4 *vertices [[buffer(0)]]) {
    VertexOut out;
    out.position = float4(vertices[vid].xy, 0, 1);
    out.texCoord = vertices[vid].zw;
    return out;
}

fragment half4 videoFragment(VertexOut in [[stage_in]], texture2d<half> tex [[texture(0)]]) {
    constexpr sampler s(mag_filter::linear, min_filter::linear);
    return tex.sample(s, in.texCoord);
}

// 2. Cursor Shaders
struct CursorUniforms {
    float2 position; // normalized cursor position (0..1, where 0,0 is top-left)
    float2 size;     // cursor size in NDC (Normalized Device Coordinates)
};

vertex VertexOut cursorVertex(uint vid [[vertex_id]], constant CursorUniforms &uniforms [[buffer(0)]]) {
    // Convert normalized coordinates (0..1, top-left origin) to NDC (-1..1, bottom-left origin)
    float2 ndcPos = float2(uniforms.position.x * 2.0 - 1.0, (1.0 - uniforms.position.y) * 2.0 - 1.0);
    float2 ndcSize = uniforms.size;

    // Quad vertices: top-left, top-right, bottom-left, bottom-right
    float2 positions[4] = {
        float2(ndcPos.x, ndcPos.y),                     // top-left
        float2(ndcPos.x + ndcSize.x, ndcPos.y),           // top-right
        float2(ndcPos.x, ndcPos.y - ndcSize.y),           // bottom-left
        float2(ndcPos.x + ndcSize.x, ndcPos.y - ndcSize.y)  // bottom-right
    };

    float2 texCoords[4] = {
        float2(0.0, 0.0), // top-left
        float2(1.0, 0.0), // top-right
        float2(0.0, 1.0), // bottom-left
        float2(1.0, 1.0)  // bottom-right
    };

    VertexOut out;
    out.position = float4(positions[vid], 0, 1);
    out.texCoord = texCoords[vid];
    return out;
}

fragment half4 cursorFragment(VertexOut in [[stage_in]], texture2d<half> tex [[texture(0)]]) {
    constexpr sampler s(mag_filter::linear, min_filter::linear);
    half4 color = tex.sample(s, in.texCoord);

    // Discard transparent pixels to enable smooth alpha cutouts of the cursor shape
    if (color.a < 0.05) {
        discard_fragment();
    }

    return color;
}

import Foundation

public enum PacketType: UInt8 {
    case handshake = 0
    case handshakeAck = 1
    case frameHeader = 2
    case frameChunk = 3
    case cursorUpdate = 4
    case inputEvent = 5
    case control = 6
    case ping = 7
    case audioFrame = 8
}

public struct PacketHeader {
    public let magic: UInt16
    public let type: PacketType
    public let sequence: UInt32
    public let timestamp: UInt32
    public let flags: UInt8

    public init(type: PacketType, sequence: UInt32, timestamp: UInt32, flags: UInt8 = 0) {
        self.magic = ERDConstants.magic
        self.type = type
        self.sequence = sequence
        self.timestamp = timestamp
        self.flags = flags
    }

    public func serialize() -> Data {
        var data = Data(capacity: ERDConstants.packetHeaderSize)
        var m = magic.littleEndian; data.append(Data(bytes: &m, count: 2))
        var t = type.rawValue;      data.append(Data(bytes: &t, count: 1))
        var s = sequence.littleEndian; data.append(Data(bytes: &s, count: 4))
        var ts = timestamp.littleEndian; data.append(Data(bytes: &ts, count: 4))
        var f = flags;              data.append(Data(bytes: &f, count: 1))
        return data
    }

    public static func deserialize(from data: Data) -> PacketHeader? {
        guard data.count >= ERDConstants.packetHeaderSize else { return nil }
        let magic = data.subdata(in: 0..<2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        guard magic == ERDConstants.magic else { return nil }
        guard let type = PacketType(rawValue: data[2]) else { return nil }
        let seq = data.subdata(in: 3..<7).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let ts = data.subdata(in: 7..<11).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let flags = data[11]
        return PacketHeader(type: type, sequence: seq, timestamp: ts, flags: flags)
    }
}

import Foundation

public struct FrameHeaderPayload {
    public let frameId: UInt32
    public let width: UInt16
    public let height: UInt16
    public let isKeyFrame: Bool
    public let totalChunks: UInt16
    public let totalSize: UInt32

    public static let size = 16

    public init(frameId: UInt32, width: UInt16, height: UInt16, isKeyFrame: Bool, totalChunks: UInt16, totalSize: UInt32) {
        self.frameId = frameId; self.width = width; self.height = height
        self.isKeyFrame = isKeyFrame; self.totalChunks = totalChunks; self.totalSize = totalSize
    }

    public func serialize() -> Data {
        var d = Data(capacity: FrameHeaderPayload.size)
        var fid = frameId.littleEndian; d.append(Data(bytes: &fid, count: 4))
        var w = width.littleEndian;     d.append(Data(bytes: &w, count: 2))
        var h = height.littleEndian;    d.append(Data(bytes: &h, count: 2))
        var kf: UInt8 = isKeyFrame ? 1 : 0; d.append(Data(bytes: &kf, count: 1))
        var tc = totalChunks.littleEndian; d.append(Data(bytes: &tc, count: 2))
        // 1 byte padding
        var pad: UInt8 = 0; d.append(Data(bytes: &pad, count: 1))
        var ts = totalSize.littleEndian; d.append(Data(bytes: &ts, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> FrameHeaderPayload? {
        guard data.count >= size else { return nil }
        let fid = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let w = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let h = data.subdata(in: 6..<8).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let kf = data[8] != 0
        let tc = data.subdata(in: 9..<11).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let ts = data.subdata(in: 12..<16).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        return FrameHeaderPayload(frameId: fid, width: w, height: h, isKeyFrame: kf, totalChunks: tc, totalSize: ts)
    }
}

public struct FrameChunkPayload {
    public let frameId: UInt32
    public let chunkIndex: UInt16
    public let chunkData: Data

    public static let headerSize = 6

    public init(frameId: UInt32, chunkIndex: UInt16, chunkData: Data) {
        self.frameId = frameId; self.chunkIndex = chunkIndex; self.chunkData = chunkData
    }

    public func serialize() -> Data {
        var d = Data(capacity: FrameChunkPayload.headerSize + chunkData.count)
        var fid = frameId.littleEndian; d.append(Data(bytes: &fid, count: 4))
        var ci = chunkIndex.littleEndian; d.append(Data(bytes: &ci, count: 2))
        d.append(chunkData)
        return d
    }

    public static func deserialize(from data: Data) -> FrameChunkPayload? {
        guard data.count >= headerSize else { return nil }
        let fid = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let ci = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let chunk = data.subdata(in: headerSize..<data.count)
        return FrameChunkPayload(frameId: fid, chunkIndex: ci, chunkData: chunk)
    }
}

import Foundation

public enum InputEventType: UInt8 {
    case mouseMove = 0
    case leftMouseDown = 1
    case leftMouseUp = 2
    case rightMouseDown = 3
    case rightMouseUp = 4
    case scrollWheel = 5
    case keyDown = 6
    case keyUp = 7
    case flagsChanged = 8
    case leftMouseDragged = 9
    case rightMouseDragged = 10
}

public struct ModifierFlags: OptionSet {
    public let rawValue: UInt16
    public init(rawValue: UInt16) { self.rawValue = rawValue }

    public static let shift   = ModifierFlags(rawValue: 1 << 0)
    public static let control = ModifierFlags(rawValue: 1 << 1)
    public static let option  = ModifierFlags(rawValue: 1 << 2)
    public static let command = ModifierFlags(rawValue: 1 << 3)
    public static let capsLock = ModifierFlags(rawValue: 1 << 4)
}

public struct InputEventPayload {
    public let type: InputEventType
    public let x: Float
    public let y: Float
    public let keyCode: UInt16
    public let modifiers: ModifierFlags
    public let scrollDeltaX: Float
    public let scrollDeltaY: Float

    public static let size = 21

    public init(type: InputEventType, x: Float, y: Float, keyCode: UInt16 = 0,
                modifiers: ModifierFlags = [], scrollDeltaX: Float = 0, scrollDeltaY: Float = 0) {
        self.type = type; self.x = x; self.y = y; self.keyCode = keyCode
        self.modifiers = modifiers; self.scrollDeltaX = scrollDeltaX; self.scrollDeltaY = scrollDeltaY
    }

    public func serialize() -> Data {
        var d = Data(capacity: InputEventPayload.size)
        var t = type.rawValue; d.append(Data(bytes: &t, count: 1))
        var fx = x.bitPattern.littleEndian; d.append(Data(bytes: &fx, count: 4))
        var fy = y.bitPattern.littleEndian; d.append(Data(bytes: &fy, count: 4))
        var kc = keyCode.littleEndian; d.append(Data(bytes: &kc, count: 2))
        var mf = modifiers.rawValue.littleEndian; d.append(Data(bytes: &mf, count: 2))
        var sdx = scrollDeltaX.bitPattern.littleEndian; d.append(Data(bytes: &sdx, count: 4))
        var sdy = scrollDeltaY.bitPattern.littleEndian; d.append(Data(bytes: &sdy, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> InputEventPayload? {
        guard data.count >= size else { return nil }
        guard let t = InputEventType(rawValue: data[0]) else { return nil }
        let x = Float(bitPattern: data.subdata(in: 1..<5).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let y = Float(bitPattern: data.subdata(in: 5..<9).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let kc = data.subdata(in: 9..<11).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let mf = ModifierFlags(rawValue: data.subdata(in: 11..<13).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        let sdx = Float(bitPattern: data.subdata(in: 13..<17).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let sdy = Float(bitPattern: data.subdata(in: 17..<21).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        return InputEventPayload(type: t, x: x, y: y, keyCode: kc, modifiers: mf, scrollDeltaX: sdx, scrollDeltaY: sdy)
    }
}

import Foundation

public enum ControlMessageType: UInt8 {
    case requestKeyFrame = 0
    case startStream = 1
    case stopStream = 2
    case disconnect = 3
    case ping = 4
    case pong = 5
    case bitrateAdjust = 6
    case streamConfigRequest = 7
    case streamConfigResponse = 8
    case streamConfigReject = 9
    case streamConfigError = 10
    case clipboardSyncRequest = 11
    case clipboardSyncUpdate = 12
    case clipboardSyncError = 13
}

public struct ControlMessage {
    public let type: ControlMessageType
    public let payload: Data?

    public init(type: ControlMessageType, payload: Data? = nil) {
        self.type = type
        self.payload = payload
    }

    public func serialize() -> Data {
        var d = Data([type.rawValue])
        if let payload = payload {
            d.append(payload)
        }
        return d
    }

    public static func deserialize(from data: Data) -> ControlMessage? {
        guard data.count >= 1, let t = ControlMessageType(rawValue: data[0]) else { return nil }
        let payload: Data? = data.count > 1 ? data.subdata(in: 1..<data.count) : nil
        return ControlMessage(type: t, payload: payload)
    }
}

public struct BitrateAdjustPayload {
    public let targetBitrate: Int32

    public static let size = 4

    public init(targetBitrate: Int32) {
        self.targetBitrate = targetBitrate
    }

    public func serialize() -> Data {
        var d = Data(capacity: BitrateAdjustPayload.size)
        var br = targetBitrate.littleEndian
        d.append(Data(bytes: &br, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> BitrateAdjustPayload? {
        guard data.count >= size else { return nil }
        let br = data.withUnsafeBytes { $0.load(as: Int32.self).littleEndian }
        return BitrateAdjustPayload(targetBitrate: br)
    }
}

public struct CursorUpdate {
    public let x: Float
    public let y: Float
    public let cursorType: UInt8

    public static let size = 9

    public init(x: Float, y: Float, cursorType: UInt8 = 0) {
        self.x = x; self.y = y; self.cursorType = cursorType
    }

    public func serialize() -> Data {
        var d = Data(capacity: CursorUpdate.size)
        var fx = x.bitPattern.littleEndian; d.append(Data(bytes: &fx, count: 4))
        var fy = y.bitPattern.littleEndian; d.append(Data(bytes: &fy, count: 4))
        var ct = cursorType; d.append(Data(bytes: &ct, count: 1))
        return d
    }

    public static func deserialize(from data: Data) -> CursorUpdate? {
        guard data.count >= size else { return nil }
        let x = Float(bitPattern: data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let y = Float(bitPattern: data.subdata(in: 4..<8).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        return CursorUpdate(x: x, y: y, cursorType: data[8])
    }
}

public class AtomicBool {
    private let lock = NSLock()
    private var _value: Bool

    public init(_ value: Bool = false) { _value = value }

    public var value: Bool {
        get { lock.lock(); defer { lock.unlock() }; return _value }
        set { lock.lock(); defer { lock.unlock() }; _value = newValue }
    }
}

import Foundation
import Network

public class UDPChannel {
    private var connection: NWConnection?
    private var listener: NWListener?
    private let queue = DispatchQueue(label: "eclipticrd.udp", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var sequenceCounter: UInt32 = 0
    private let seqLock = NSLock()

    public var onReceive: (@Sendable (Data, NWEndpoint?) -> Void)?
    public var onReady: (@Sendable () -> Void)?

    private let _isReady = AtomicBool(false)
    public var isReady: Bool { _isReady.value }

    public init() {
        queue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    // MARK: - Server side

    public func startListening(port: UInt16) throws {
        let params = NWParameters.udp
        params.allowLocalEndpointReuse = true
        listener = try NWListener(using: params, on: NWEndpoint.Port(rawValue: port)!)
        listener?.newConnectionHandler = { [weak self] conn in
            guard let self = self else { return }
            self.connection = conn
            conn.stateUpdateHandler = { [weak self] state in
                if case .ready = state {
                    ERDLog.network("[UDP] Listener connection ready")
                    self?._isReady.value = true
                    self?.onReady?()
                }
            }
            conn.start(queue: self.queue)
            self.receiveLoop(on: conn)
        }
        listener?.start(queue: queue)
    }

    // MARK: - Client side

    public func connect(host: String, port: UInt16) {
        let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(host), port: NWEndpoint.Port(rawValue: port)!)
        connect(to: endpoint)
    }

    public func connect(to endpoint: NWEndpoint) {
        let params = NWParameters.udp
        params.allowLocalEndpointReuse = true
        let conn = NWConnection(to: endpoint, using: params)
        queue.async { [weak self] in
            guard let self = self else { return }
            self.connection = conn
            conn.stateUpdateHandler = { [weak self] state in
                switch state {
                case .ready:
                    ERDLog.network("[UDP] Connected to \(endpoint)")
                    self?._isReady.value = true
                    self?.onReady?()
                case .failed(let e): ERDLog.error("[UDP] Connection failed: \(e)")
                default: break
                }
            }
            conn.start(queue: self.queue)
            self.receiveLoop(on: conn)
        }
    }

    // MARK: - Send

    public func send(_ data: Data, to endpoint: NWEndpoint? = nil) {
        guard let conn = connection else { return }
        conn.send(content: data, completion: .contentProcessed { error in
            if let error = error { ERDLog.error("[UDP] Send error: \(error)") }
        })
    }

    public func sendPacket(type: PacketType, payload: Data, to endpoint: NWEndpoint? = nil) {
        seqLock.lock()
        sequenceCounter += 1
        let seq = sequenceCounter
        seqLock.unlock()
        let ts = UInt32(truncatingIfNeeded: UInt64(Date().timeIntervalSince1970 * 1000))
        let header = PacketHeader(type: type, sequence: seq, timestamp: ts)
        var packet = header.serialize()
        packet.append(payload)
        send(packet, to: endpoint)
    }

    /// Send a small datagram to trigger the other side's listener to register us
    public func sendPing() {
        // Send 1-byte ping to trigger connection handler on the listener side
        send(Data([0xFF]))
    }

    // MARK: - Stop

    public func stop() {
        let work = {
            self.connection?.cancel()
            self.connection = nil
            self.listener?.cancel()
            self.listener = nil
            self.sequenceCounter = 0
            self._isReady.value = false
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    // MARK: - Internal

    private func receiveLoop(on conn: NWConnection) {
        conn.receiveMessage { [weak self] content, _, isComplete, error in
            guard let self = self else { return }
            if let data = content, data.count > 1 { // Ignore 1-byte pings
                self.onReceive?(data, conn.currentPath?.remoteEndpoint)
            }
            // Always re-arm for more data
            if conn.state == .ready {
                self.receiveLoop(on: conn)
            }
        }
    }
}

import Foundation
import Network

public class TCPChannel {
    private var connection: NWConnection?
    private var listener: NWListener?
    private let queue = DispatchQueue(label: "eclipticrd.tcp", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var receiveBuffer = Data()
    private var timeoutWorkItem: DispatchWorkItem?
    private var didNotifyDisconnect = false

    public var onConnect: (@Sendable () -> Void)?
    public var onDisconnect: (@Sendable () -> Void)?
    public var onReceive: (@Sendable (Data) -> Void)?

    public var remoteHostIP: String? {
        guard let endpoint = connection?.currentPath?.remoteEndpoint else { return nil }
        if case .hostPort(let host, _) = endpoint { return "\(host)" }
        return nil
    }

    public init() {
        queue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    // MARK: - Server side

    public func startListening(port: UInt16) throws {
        let params = NWParameters.tcp
        listener = try NWListener(using: params, on: NWEndpoint.Port(rawValue: port)!)
        listener?.newConnectionHandler = { [weak self] conn in
            self?.setupConnection(conn)
        }
        listener?.stateUpdateHandler = { state in
            ERDLog.network("[TCP] Listener state: \(state)")
        }
        listener?.start(queue: queue)
    }

    public func advertiseService(name: String) {
        listener?.service = NWListener.Service(name: name, type: ERDConstants.bonjourServiceType, domain: ERDConstants.bonjourDomain)
    }

    // MARK: - Client side

    public func connect(host: String, port: UInt16) {
        let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(host), port: NWEndpoint.Port(rawValue: port)!)
        connect(to: endpoint)
    }

    public func connect(to endpoint: NWEndpoint) {
        let conn = NWConnection(to: endpoint, using: .tcp)
        queue.async { [weak self] in
            self?.setupConnection(conn)
        }
        setTimeout(ERDConstants.connectionTimeout)
    }

    public func connectICE(endpoints: [NWEndpoint]) {
        for endpoint in endpoints {
            let conn = NWConnection(to: endpoint, using: .tcp)
            conn.stateUpdateHandler = { [weak self] state in
                guard let self = self else { return }
                switch state {
                case .ready:
                    if self.connection == nil {
                        self.connection = conn
                        self.didNotifyDisconnect = false
                        self.cancelTimeout()
                        ERDLog.network("[Client] ICE Won by \(endpoint)")
                        conn.stateUpdateHandler = { [weak self] state in
                            switch state {
                            case .ready:
                                break
                            case .failed(let err):
                                ERDLog.error("[TCP] ICE connection failed: \(err)")
                                self?.notifyDisconnect()
                            case .cancelled:
                                self?.notifyDisconnect()
                            default:
                                break
                            }
                        }
                        self.startReceiving()
                        self.onConnect?()
                    } else {
                        conn.cancel()
                    }
                case .failed, .cancelled:
                    break
                default: break
                }
            }
            conn.start(queue: queue)
        }
        setTimeout(ERDConstants.connectionTimeout)
    }

    public func setTimeout(_ seconds: Double) {
        cancelTimeout()
        let work = DispatchWorkItem { [weak self] in
            guard let self = self else { return }
            ERDLog.error("[TCP] Connection timeout after \(seconds)s")
            self.connection?.cancel()
            self.connection = nil
            self.notifyDisconnect()
        }
        timeoutWorkItem = work
        queue.asyncAfter(deadline: .now() + seconds, execute: work)
    }

    // MARK: - Send

    public func send(_ data: Data) {
        // Length-prefixed framing: 4-byte little-endian length + payload
        var len = UInt32(data.count).littleEndian
        var frame = Data(bytes: &len, count: 4)
        frame.append(data)
        connection?.send(content: frame, completion: .contentProcessed { error in
            if let error = error {
                ERDLog.error("[TCP] Send error: \(error)")
            }
        })
    }

    public func sendControl(_ msg: ControlMessage) {
        let header = PacketHeader(type: .control, sequence: 0, timestamp: currentTimestamp())
        var packet = header.serialize()
        packet.append(msg.serialize())
        send(packet)
    }

    public func sendInput(_ input: InputEventPayload) {
        let header = PacketHeader(type: .inputEvent, sequence: 0, timestamp: currentTimestamp())
        var packet = header.serialize()
        packet.append(input.serialize())
        send(packet)
    }

    // MARK: - Stop

    public func stop() {
        let work = {
            self.cancelTimeout()
            self.connection?.cancel()
            self.connection = nil
            self.listener?.cancel()
            self.listener = nil
            self.receiveBuffer = Data()
            self.notifyDisconnect()
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    public func disconnectConnection() {
        let work = {
            self.cancelTimeout()
            self.connection?.cancel()
            self.connection = nil
            self.receiveBuffer = Data()
            self.notifyDisconnect()
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    // MARK: - Internal

    private func cancelTimeout() {
        timeoutWorkItem?.cancel()
        timeoutWorkItem = nil
    }

    private func setupConnection(_ conn: NWConnection) {
        connection = conn
        didNotifyDisconnect = false
        conn.stateUpdateHandler = { [weak self] state in
            switch state {
            case .ready:
                self?.cancelTimeout()
                ERDLog.network("[TCP] Connected to \(conn.endpoint)")
                self?.startReceiving()
                self?.onConnect?()
            case .failed(let err):
                ERDLog.error("[TCP] Connection failed: \(err)")
                self?.notifyDisconnect()
            case .cancelled:
                self?.notifyDisconnect()
            default: break
            }
        }
        conn.start(queue: queue)
    }

    private func notifyDisconnect() {
        guard !didNotifyDisconnect else { return }
        didNotifyDisconnect = true
        onDisconnect?()
    }

    private func startReceiving() {
        connection?.receive(minimumIncompleteLength: 1, maximumLength: 262144) { [weak self] content, _, isComplete, error in
            guard let self = self else { return }
            if let data = content {
                self.receiveBuffer.append(data)
                self.processBuffer()
            }
            if let error = error {
                ERDLog.error("[TCP] Receive error: \(error)")
                self.notifyDisconnect()
                return
            }
            if !isComplete {
                self.startReceiving()
            } else {
                self.notifyDisconnect()
            }
        }
    }

    private func processBuffer() {
        while receiveBuffer.count >= 4 {
            let length = Int(receiveBuffer.prefix(4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
            guard length > 0, length <= 16_777_216 else {
                // Invalid length — drop buffer to recover
                ERDLog.error("[TCP] Invalid frame length: \(length), dropping buffer")
                receiveBuffer.removeAll()
                break
            }
            guard receiveBuffer.count >= 4 + length else {
                break
            }
            let payload = receiveBuffer.subdata(in: 4..<(4 + length))
            receiveBuffer.removeSubrange(0..<(4 + length))
            onReceive?(payload)
        }
    }

    private func currentTimestamp() -> UInt32 {
        UInt32(truncatingIfNeeded: UInt64(Date().timeIntervalSince1970 * 1000))
    }
}

import Foundation

public struct StreamConfiguration {
    public let width: UInt32
    public let height: UInt32
    public let bitrate: UInt32
    public let framesPerSecond: UInt16

    public static let size = 14

    public init(width: UInt32, height: UInt32, bitrate: UInt32, framesPerSecond: UInt16) {
        self.width = width
        self.height = height
        self.bitrate = bitrate
        self.framesPerSecond = framesPerSecond
    }

    public func serialize() -> Data {
        var data = Data(capacity: Self.size)
        var w = width.littleEndian; data.append(Data(bytes: &w, count: 4))
        var h = height.littleEndian; data.append(Data(bytes: &h, count: 4))
        var b = bitrate.littleEndian; data.append(Data(bytes: &b, count: 4))
        var fps = framesPerSecond.littleEndian; data.append(Data(bytes: &fps, count: 2))
        return data
    }

    public static func deserialize(from data: Data) -> StreamConfiguration? {
        guard data.count >= size else { return nil }
        let width = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let height = data.subdata(in: 4..<8).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let bitrate = data.subdata(in: 8..<12).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let fps = data.subdata(in: 12..<14).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        return StreamConfiguration(width: width, height: height, bitrate: bitrate, framesPerSecond: fps)
    }
}

public enum StreamConfigurationErrorCode: UInt8 {
    case invalidRequest = 0
    case unsupportedDimensions = 1
    case unsupportedBitrate = 2
    case unsupportedFPS = 3
    case rejectedByPeer = 4
}

public struct StreamConfigurationRequestPayload {
    public let requestID: UInt32
    public let desiredConfiguration: StreamConfiguration

    public static let size = 4 + StreamConfiguration.size

    public init(requestID: UInt32, desiredConfiguration: StreamConfiguration) {
        self.requestID = requestID
        self.desiredConfiguration = desiredConfiguration
    }

    public func serialize() -> Data {
        var data = Data(capacity: Self.size)
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        data.append(desiredConfiguration.serialize())
        return data
    }

    public static func deserialize(from data: Data) -> StreamConfigurationRequestPayload? {
        guard data.count >= size else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let desiredConfiguration = StreamConfiguration.deserialize(from: data.subdata(in: 4..<data.count)) else { return nil }
        return StreamConfigurationRequestPayload(requestID: requestID, desiredConfiguration: desiredConfiguration)
    }
}

public struct StreamConfigurationResponsePayload {
