public struct StreamConfigurationRejectPayload {
    public let requestID: UInt32
    public let reason: StreamConfigurationErrorCode
    public let message: String

    public init(requestID: UInt32, reason: StreamConfigurationErrorCode, message: String) {
        self.requestID = requestID
        self.reason = reason
        self.message = message
    }

    public func serialize() -> Data {
        var data = Data()
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var code = reason.rawValue; data.append(Data(bytes: &code, count: 1))
        let messageData = message.data(using: .utf8) ?? Data()
        var length = UInt16(min(messageData.count, Int(UInt16.max))).littleEndian
        data.append(Data(bytes: &length, count: 2))
        data.append(messageData.prefix(Int(length)))
        return data
    }

    public static func deserialize(from data: Data) -> StreamConfigurationRejectPayload? {
        guard data.count >= 7 else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let reason = StreamConfigurationErrorCode(rawValue: data[4]) else { return nil }
        let length = Int(data.subdata(in: 5..<7).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard data.count >= 7 + length else { return nil }
        let message = String(data: data.subdata(in: 7..<(7 + length)), encoding: .utf8) ?? ""
        return StreamConfigurationRejectPayload(requestID: requestID, reason: reason, message: message)
    }
}

public struct StreamConfigurationErrorPayload {
    public let requestID: UInt32
    public let errorCode: StreamConfigurationErrorCode
    public let message: String

    public init(requestID: UInt32, errorCode: StreamConfigurationErrorCode, message: String) {
        self.requestID = requestID
        self.errorCode = errorCode
        self.message = message
    }

    public func serialize() -> Data {
        var data = Data()
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var code = errorCode.rawValue; data.append(Data(bytes: &code, count: 1))
        let messageData = message.data(using: .utf8) ?? Data()
        var length = UInt16(min(messageData.count, Int(UInt16.max))).littleEndian
        data.append(Data(bytes: &length, count: 2))
        data.append(messageData.prefix(Int(length)))
        return data
    }

    public static func deserialize(from data: Data) -> StreamConfigurationErrorPayload? {
        guard data.count >= 7 else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let errorCode = StreamConfigurationErrorCode(rawValue: data[4]) else { return nil }
        let length = Int(data.subdata(in: 5..<7).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard data.count >= 7 + length else { return nil }
        let message = String(data: data.subdata(in: 7..<(7 + length)), encoding: .utf8) ?? ""
        return StreamConfigurationErrorPayload(requestID: requestID, errorCode: errorCode, message: message)
    }
}

public enum ClipboardSyncDirection: UInt8 {
    case hostToClient = 0
    case clientToHost = 1
    case bidirectional = 2
}

public enum ClipboardSyncOrigin: UInt8 {
    case localPasteboard = 0
    case remotePasteboard = 1
    case syncedFromPeer = 2
}

public struct ClipboardSyncRequestPayload {
    public let requestID: UInt32
    public let direction: ClipboardSyncDirection
    public let origin: ClipboardSyncOrigin

    public static let size = 6

    public init(requestID: UInt32, direction: ClipboardSyncDirection, origin: ClipboardSyncOrigin) {
        self.requestID = requestID
        self.direction = direction
        self.origin = origin
    }

    public func serialize() -> Data {
        var data = Data(capacity: Self.size)
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var dir = direction.rawValue; data.append(Data(bytes: &dir, count: 1))
        var org = origin.rawValue; data.append(Data(bytes: &org, count: 1))
        return data
    }

    public static func deserialize(from data: Data) -> ClipboardSyncRequestPayload? {
        guard data.count >= size else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let direction = ClipboardSyncDirection(rawValue: data[4]), let origin = ClipboardSyncOrigin(rawValue: data[5]) else { return nil }
        return ClipboardSyncRequestPayload(requestID: requestID, direction: direction, origin: origin)
    }
}

public struct ClipboardSyncUpdatePayload {
    public let requestID: UInt32
    public let direction: ClipboardSyncDirection
    public let origin: ClipboardSyncOrigin
    public let text: String

    public init(requestID: UInt32, direction: ClipboardSyncDirection, origin: ClipboardSyncOrigin, text: String) {
        self.requestID = requestID
        self.direction = direction
        self.origin = origin
        self.text = text
    }

    public func serialize() -> Data? {
        let textData = text.data(using: .utf8) ?? Data()
        guard textData.count <= ERDConstants.maxClipboardTextBytes else { return nil }
        var data = Data()
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var dir = direction.rawValue; data.append(Data(bytes: &dir, count: 1))
        var org = origin.rawValue; data.append(Data(bytes: &org, count: 1))
        var length = UInt16(textData.count).littleEndian; data.append(Data(bytes: &length, count: 2))
        data.append(textData)
        return data
    }

    public static func deserialize(from data: Data) -> ClipboardSyncUpdatePayload? {
        guard data.count >= 8 else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let direction = ClipboardSyncDirection(rawValue: data[4]), let origin = ClipboardSyncOrigin(rawValue: data[5]) else { return nil }
        let length = Int(data.subdata(in: 6..<8).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard length <= ERDConstants.maxClipboardTextBytes, data.count >= 8 + length else { return nil }
        let text = String(data: data.subdata(in: 8..<(8 + length)), encoding: .utf8) ?? ""
        return ClipboardSyncUpdatePayload(requestID: requestID, direction: direction, origin: origin, text: text)
    }
}

public struct ClipboardSyncErrorPayload {
    public let requestID: UInt32
    public let direction: ClipboardSyncDirection
    public let origin: ClipboardSyncOrigin
    public let errorCode: UInt8
    public let message: String

    public init(requestID: UInt32, direction: ClipboardSyncDirection, origin: ClipboardSyncOrigin, errorCode: UInt8, message: String) {
        self.requestID = requestID
        self.direction = direction
        self.origin = origin
        self.errorCode = errorCode
        self.message = message
    }

    public func serialize() -> Data {
        var data = Data()
        var id = requestID.littleEndian; data.append(Data(bytes: &id, count: 4))
        var dir = direction.rawValue; data.append(Data(bytes: &dir, count: 1))
        var org = origin.rawValue; data.append(Data(bytes: &org, count: 1))
        var code = errorCode; data.append(Data(bytes: &code, count: 1))
        let messageData = message.data(using: .utf8) ?? Data()
        var length = UInt16(min(messageData.count, Int(UInt16.max))).littleEndian
        data.append(Data(bytes: &length, count: 2))
        data.append(messageData.prefix(Int(length)))
        return data
    }

    public static func deserialize(from data: Data) -> ClipboardSyncErrorPayload? {
        guard data.count >= 9 else { return nil }
        let requestID = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard let direction = ClipboardSyncDirection(rawValue: data[4]), let origin = ClipboardSyncOrigin(rawValue: data[5]) else { return nil }
        let errorCode = data[6]
        let length = Int(data.subdata(in: 7..<9).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard data.count >= 9 + length else { return nil }
        let message = String(data: data.subdata(in: 9..<(9 + length)), encoding: .utf8) ?? ""
        return ClipboardSyncErrorPayload(requestID: requestID, direction: direction, origin: origin, errorCode: errorCode, message: message)
    }
}

import Foundation
import VideoToolbox
import CoreMedia

public enum VideoEncoderError: Error {
    case sessionCreationFailed
    case encodingFailed
}

public class VideoEncoder {
    private var session: VTCompressionSession?
    private let encoderQueue = DispatchQueue(label: "eclipticrd.encoder", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var frameCount: Int64 = 0
    private var retainedSelf: Unmanaged<VideoEncoder>?

    private let width: Int
    private let height: Int
    private let bitrate: Int
    private let fps: Int
    private var pendingForceKeyFrame = AtomicBool(false)

    public var onEncodedFrame: ((Data, Bool) -> Void)?

    public init(width: Int, height: Int, bitrate: Int = ERDConstants.defaultBitrate, fps: Int = ERDConstants.defaultFPS) {
        self.width = width; self.height = height; self.bitrate = bitrate; self.fps = fps
        encoderQueue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    public func start() throws {
        retainedSelf = Unmanaged.passRetained(self)

        let err = VTCompressionSessionCreate(
            allocator: kCFAllocatorDefault,
            width: Int32(width), height: Int32(height),
            codecType: kCMVideoCodecType_HEVC,
            encoderSpecification: nil, imageBufferAttributes: nil, compressedDataAllocator: nil,
            outputCallback: encoderCallback,
            refcon: retainedSelf!.toOpaque(),
            compressionSessionOut: &session
        )
        guard err == noErr, let session = session else { throw VideoEncoderError.sessionCreationFailed }

        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_RealTime, value: kCFBooleanTrue)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AllowFrameReordering, value: kCFBooleanFalse)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AverageBitRate, value: bitrate as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_MaxKeyFrameInterval, value: ERDConstants.keyFrameInterval as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ExpectedFrameRate, value: fps as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ProfileLevel, value: kVTProfileLevel_HEVC_Main_AutoLevel)

        VTCompressionSessionPrepareToEncodeFrames(session)
        ERDLog.video("[Encoder] Started: H.265 \(width)x\(height) @\(bitrate/1_000_000)Mbps")
    }

    public func stop() {
        let work = {
            if let session = self.session {
                VTCompressionSessionInvalidate(session)
                self.session = nil
            }
            self.retainedSelf?.release()
            self.retainedSelf = nil
            self.frameCount = 0
            ERDLog.video("[Encoder] Stopped")
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            encoderQueue.sync { work() }
        }
    }

    public func encode(_ sampleBuffer: CMSampleBuffer) {
        encoderQueue.async { [weak self] in
            guard let self = self else { return }
            guard let session = self.session else { return }
            guard let imageBuffer = CMSampleBufferGetImageBuffer(sampleBuffer) else {
                return
            }
            let pts = CMTime(value: self.frameCount, timescale: CMTimeScale(self.fps))
            self.frameCount += 1

            var frameProps: CFDictionary? = nil
            if self.pendingForceKeyFrame.value {
                self.pendingForceKeyFrame.value = false
                frameProps = [kVTEncodeFrameOptionKey_ForceKeyFrame: true] as CFDictionary
            }

            VTCompressionSessionEncodeFrame(session, imageBuffer: imageBuffer, presentationTimeStamp: pts,
                                            duration: .invalid, frameProperties: frameProps, sourceFrameRefcon: nil, infoFlagsOut: nil)
        }
    }

    public func forceKeyFrame() {
        pendingForceKeyFrame.value = true
    }

    public func updateBitrate(_ newBitrate: Int) {
        encoderQueue.async { [weak self] in
            guard let self = self, let session = self.session else { return }
            VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AverageBitRate, value: newBitrate as CFTypeRef)
        }
    }

    public func updateFPS(_ newFPS: Int) {
        encoderQueue.async { [weak self] in
            guard let self = self, let session = self.session else { return }
            VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ExpectedFrameRate, value: newFPS as CFTypeRef)
        }
    }

    fileprivate func handleEncodedFrame(_ sampleBuffer: CMSampleBuffer) {
        guard let dataBuffer = CMSampleBufferGetDataBuffer(sampleBuffer) else { return }

        let isKeyFrame: Bool = {
            guard let attachments = CMSampleBufferGetSampleAttachmentsArray(sampleBuffer, createIfNecessary: false) as? [[CFString: Any]],
                  let first = attachments.first else { return true }
            return !(first[kCMSampleAttachmentKey_NotSync] as? Bool ?? false)
        }()

        var length = 0
        var dataPointer: UnsafeMutablePointer<Int8>?
        CMBlockBufferGetDataPointer(dataBuffer, atOffset: 0, lengthAtOffsetOut: nil, totalLengthOut: &length, dataPointerOut: &dataPointer)

        guard let pointer = dataPointer, length > 0 else { return }

        var frameData = Data()

        // For keyframes, prepend VPS/SPS/PPS from the format description
        // so the decoder can create its decoding session.
        if isKeyFrame, let formatDesc = CMSampleBufferGetFormatDescription(sampleBuffer) {
            var paramCount: Int = 0
            CMVideoFormatDescriptionGetHEVCParameterSetAtIndex(formatDesc, parameterSetIndex: 0,
                parameterSetPointerOut: nil, parameterSetSizeOut: nil, parameterSetCountOut: &paramCount, nalUnitHeaderLengthOut: nil)

            for i in 0..<paramCount {
                var paramPtr: UnsafePointer<UInt8>?
                var paramSize: Int = 0
                let status = CMVideoFormatDescriptionGetHEVCParameterSetAtIndex(formatDesc, parameterSetIndex: i,
                    parameterSetPointerOut: &paramPtr, parameterSetSizeOut: &paramSize, parameterSetCountOut: nil, nalUnitHeaderLengthOut: nil)
                if status == noErr, let ptr = paramPtr, paramSize > 0 {
                    // Write 4-byte AVCC length prefix + parameter set data
                    var len = UInt32(paramSize).bigEndian
                    frameData.append(Data(bytes: &len, count: 4))
                    frameData.append(Data(bytes: ptr, count: paramSize))
                }
            }
        }

        frameData.append(Data(bytes: pointer, count: length))
        onEncodedFrame?(frameData, isKeyFrame)
    }
}

private func encoderCallback(outputCallbackRefCon: UnsafeMutableRawPointer?,
                              sourceFrameRefCon: UnsafeMutableRawPointer?,
                              status: OSStatus,
                              infoFlags: VTEncodeInfoFlags,
                              sampleBuffer: CMSampleBuffer?) {
    guard status == noErr, let sampleBuffer = sampleBuffer, let refcon = outputCallbackRefCon else { return }
    let encoder = Unmanaged<VideoEncoder>.fromOpaque(refcon).takeUnretainedValue()
    encoder.handleEncodedFrame(sampleBuffer)
}

import Foundation

public struct HandshakeCapabilities: OptionSet {
    public let rawValue: UInt64

    public init(rawValue: UInt64) {
        self.rawValue = rawValue
    }

    public static let streamConfiguration = HandshakeCapabilities(rawValue: 1 << 0)
    public static let clipboardSync = HandshakeCapabilities(rawValue: 1 << 1)
    public static let textClipboardSync = HandshakeCapabilities(rawValue: 1 << 2)
}

public struct HandshakePayload {
    public let hostname: String
    public let screenWidth: UInt16
    public let screenHeight: UInt16
    public let scaleFactor: Float
    public let protocolVersion: UInt8
    public let capabilities: HandshakeCapabilities

    public init(hostname: String, screenWidth: UInt16, screenHeight: UInt16, scaleFactor: Float, protocolVersion: UInt8 = ERDConstants.protocolVersion, capabilities: HandshakeCapabilities = []) {
        self.hostname = hostname
        self.screenWidth = screenWidth
        self.screenHeight = screenHeight
        self.scaleFactor = scaleFactor
        self.protocolVersion = protocolVersion
        self.capabilities = capabilities
    }

    public func serialize() -> Data {
        var data = Data()
        let nameData = hostname.data(using: .utf8) ?? Data()
        var nameLen = UInt16(nameData.count).littleEndian; data.append(Data(bytes: &nameLen, count: 2))
        data.append(nameData)
        var w = screenWidth.littleEndian; data.append(Data(bytes: &w, count: 2))
        var h = screenHeight.littleEndian; data.append(Data(bytes: &h, count: 2))
        var s = scaleFactor.bitPattern.littleEndian; data.append(Data(bytes: &s, count: 4))
        var version = protocolVersion; data.append(Data(bytes: &version, count: 1))
        var flags = capabilities.rawValue.littleEndian; data.append(Data(bytes: &flags, count: 8))
        return data
    }

    public static func deserialize(from data: Data) -> HandshakePayload? {
        guard data.count >= 2 else { return nil }
        var offset = 0
        let nameLen = Int(data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        offset += 2
        guard nameLen <= 1024, data.count >= offset + nameLen + 8 else { return nil }
        let hostname = String(data: data.subdata(in: offset..<offset+nameLen), encoding: .utf8) ?? ""
        offset += nameLen
        let w = data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }; offset += 2
        let h = data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }; offset += 2
        let sBits = data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let s = Float(bitPattern: sBits)
        offset += 4

        var protocolVersion = ERDConstants.legacyProtocolVersion
        var capabilities: HandshakeCapabilities = []
        if data.count >= offset + 9 {
            protocolVersion = data[offset]
            let flags = data.subdata(in: (offset + 1)..<(offset + 9)).withUnsafeBytes { $0.load(as: UInt64.self).littleEndian }
            capabilities = HandshakeCapabilities(rawValue: flags)
        }

        return HandshakePayload(hostname: hostname, screenWidth: w, screenHeight: h, scaleFactor: s, protocolVersion: protocolVersion, capabilities: capabilities)
    }
}

import Foundation
import ScreenCaptureKit
import CoreMedia
import CoreGraphics
import AppKit

public enum ScreenCaptureError: Error, Hashable {
    case noPermission
    case noDisplay
    case captureStartFailed
}

public class ScreenCapture: NSObject, SCStreamOutput, SCStreamDelegate {
    private var stream: SCStream?
    private let captureQueue = DispatchQueue(label: "eclipticrd.capture", qos: .userInteractive)
    private var display: SCDisplay?

    public var onFrame: ((CMSampleBuffer) -> Void)?
    public var onCursorPosition: ((CGPoint) -> Void)?
    public var onAudio: ((CMSampleBuffer) -> Void)?

    public private(set) var width: Int = 0
    public private(set) var height: Int = 0
    public private(set) var scaleFactor: CGFloat = 1.0

    public override init() { super.init() }

    public func getDisplayInfo() -> (width: Int, height: Int, pixelWidth: Int, pixelHeight: Int, scale: CGFloat) {
        let displayID = CGMainDisplayID()
        let w = CGDisplayPixelsWide(displayID)
        let h = CGDisplayPixelsHigh(displayID)
        let mode = CGDisplayCopyDisplayMode(displayID)
        let scale = CGFloat(mode?.pixelWidth ?? w) / CGFloat(w)
        let pw = Int(CGFloat(w) * scale)
        let ph = Int(CGFloat(h) * scale)
        return (w, h, pw, ph, scale)
    }

    public func start(fps: Int = ERDConstants.defaultFPS) async throws {
        // CGRequestScreenCaptureAccess() triggers the system prompt on first call.
        // On subsequent calls it returns the cached result without re-prompting.
        if !CGPreflightScreenCaptureAccess() {
            let granted = CGRequestScreenCaptureAccess()
            if !granted {
                // Open System Settings → Privacy → Screen Recording so the user
                // can manually toggle the permission (required for ad-hoc signed builds).
                if let url = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture") {
                    await MainActor.run { NSWorkspace.shared.open(url) }
                }
                throw ScreenCaptureError.noPermission
            }
        }

        let content = try await SCShareableContent.excludingDesktopWindows(false, onScreenWindowsOnly: true)
        guard let display = content.displays.first else { throw ScreenCaptureError.noDisplay }

        self.display = display
        let info = getDisplayInfo()
        self.width = info.width
        self.height = info.height
        self.scaleFactor = info.scale

        let filter = SCContentFilter(display: display, excludingApplications: [], exceptingWindows: [])
        let config = SCStreamConfiguration()
        config.width = info.pixelWidth
        config.height = info.pixelHeight
        config.minimumFrameInterval = CMTime(value: 1, timescale: CMTimeScale(fps))
        config.queueDepth = 5
        config.pixelFormat = kCVPixelFormatType_32BGRA
        config.showsCursor = true
        let hostAudioEnabled = UserDefaults.standard.object(forKey: "hostAudioEnabled") as? Bool ?? true
        config.capturesAudio = hostAudioEnabled

        let stream = SCStream(filter: filter, configuration: config, delegate: self)
        try stream.addStreamOutput(self, type: .screen, sampleHandlerQueue: captureQueue)
        if hostAudioEnabled {
            try stream.addStreamOutput(self, type: .audio, sampleHandlerQueue: captureQueue)
        }
        try await stream.startCapture()
        self.stream = stream
        ERDLog.video("[Capture] Started: \(width)x\(height) @\(fps)fps scale=\(scaleFactor)")
    }

    public func updateConfiguration(width: Int, height: Int, fps: Int) async throws {
        guard let stream = self.stream else {
            throw ScreenCaptureError.captureStartFailed
        }
        let config = SCStreamConfiguration()
        config.width = width
        config.height = height
        config.minimumFrameInterval = CMTime(value: 1, timescale: CMTimeScale(fps))
        config.queueDepth = 3
        config.pixelFormat = kCVPixelFormatType_32BGRA
        config.showsCursor = true

        try await stream.updateConfiguration(config)
        self.width = width
        self.height = height
        ERDLog.video("[Capture] Configuration updated: \(width)x\(height) @\(fps)fps")
    }

    public func stop() async throws {
        try await stream?.stopCapture()
        stream = nil
        ERDLog.video("[Capture] Stopped")
    }

    // MARK: - SCStreamOutput
    public func stream(_ stream: SCStream, didOutputSampleBuffer sampleBuffer: CMSampleBuffer, of type: SCStreamOutputType) {
        if type == .screen {
            onFrame?(sampleBuffer)

            // Try to extract cursor position from sample buffer attachments (private API).
            // Falls back to NSEvent.mouseLocation if the attachment is unavailable.
            if let cursor = CMGetAttachment(sampleBuffer, key: "com.apple.screencapture.cursor.position" as CFString, attachmentModeOut: nil) as? [String: Any],
               let x = cursor["x"] as? CGFloat, let y = cursor["y"] as? CGFloat {
                onCursorPosition?(CGPoint(x: x, y: y))
            } else {
                // Fallback: use NSEvent.mouseLocation (global screen coordinates, origin at bottom-left)
                // Convert to display-local coordinates accounting for multi-monitor offset
                let mouseLocation = NSEvent.mouseLocation
                if let screen = NSScreen.main {
                    let relativeX = mouseLocation.x - screen.frame.origin.x
                    let relativeY = screen.frame.maxY - mouseLocation.y
                    onCursorPosition?(CGPoint(x: relativeX, y: relativeY))
                }
            }
        } else if type == .audio {
            onAudio?(sampleBuffer)
        }
    }

    // MARK: - SCStreamDelegate
    public func stream(_ stream: SCStream, didStopWithError error: Error) {
        ERDLog.error("[Capture] Stream stopped with error: \(error)")
    }
}

import Foundation

public class FrameSender {
    private let udpChannel: UDPChannel
    private var frameIdCounter: UInt32 = 0
    private let counterLock = NSLock()

    public init(udpChannel: UDPChannel) {
        self.udpChannel = udpChannel
    }

    public func sendFrame(data: Data, width: Int, height: Int, isKeyFrame: Bool) {
        counterLock.lock()
        frameIdCounter += 1
        let frameId = frameIdCounter
        counterLock.unlock()

        let maxPayload = ERDConstants.maxPayloadSize - FrameChunkPayload.headerSize
        let totalChunks = UInt16((data.count + maxPayload - 1) / maxPayload)

        guard totalChunks <= ERDConstants.maxChunksPerFrame else {
            ERDLog.error("[FrameSender] Frame too large: \(data.count) bytes, \(totalChunks) chunks")
            return
        }

        // 1. Send frame header via UDP
        let header = FrameHeaderPayload(
            frameId: frameId, width: UInt16(width), height: UInt16(height),
            isKeyFrame: isKeyFrame, totalChunks: totalChunks, totalSize: UInt32(data.count)
        )
        udpChannel.sendPacket(type: .frameHeader, payload: header.serialize())

        // 2. Send frame chunks via UDP
        var offset = 0
        var chunkIndex: UInt16 = 0
        while offset < data.count {
            let end = min(offset + maxPayload, data.count)
            let chunkData = data.subdata(in: offset..<end)
            let chunk = FrameChunkPayload(frameId: frameId, chunkIndex: chunkIndex, chunkData: chunkData)
            udpChannel.sendPacket(type: .frameChunk, payload: chunk.serialize())
            offset = end
            chunkIndex += 1
        }
    }

    public func sendCursorUpdate(x: Float, y: Float, cursorType: UInt8 = 0) {
        let cursor = CursorUpdate(x: x, y: y, cursorType: cursorType)
        udpChannel.sendPacket(type: .cursorUpdate, payload: cursor.serialize())
    }
}

import Foundation
import Network
import CoreMedia
import CoreGraphics

public class ServerCore {
    public static let shared = ServerCore()

    private let tcpChannel = TCPChannel()
    private let udpChannel = UDPChannel()
    private var frameSender: FrameSender?
    private var inputReceiver: InputReceiver?
    private let screenCapture = ScreenCapture()
    private var videoEncoder: VideoEncoder?
    private var hostname: String = ""
    public private(set) var isRunning = false
    private var isStreaming = AtomicBool(false)
    // Protects inputReceiver, frameSender, videoEncoder from concurrent access
    // between tcpChannel.onReceive (TCP queue) and startStreaming/stopStreaming (async context).
    private let stateQueue = DispatchQueue(label: "eclipticrd.server.state")

    private var heartbeatTimer: DispatchSourceTimer?
    private let heartbeatQueue = DispatchQueue(label: "eclipticrd.server.heartbeat")
    private var lastPongTime: Date = Date()
    private let pongLock = NSLock()

    private var clipboardMonitor: ClipboardMonitor?
    private var peerCapabilities: HandshakeCapabilities = []
    private var activeStreamConfig: StreamConfiguration?

    public var onRunningChanged: (@Sendable (Bool) -> Void)?

    private init() {}

    public func start(pin: String? = nil) async {
        hostname = ProcessInfo.processInfo.hostName

        do {
            // 1. Start TCP listener for control/input
            try tcpChannel.startListening(port: ERDConstants.tcpPort)
            isRunning = true
            onRunningChanged?(true)

            // 2. Start UDP listener for video frames
            try udpChannel.startListening(port: ERDConstants.udpPort)
            ERDLog.info("[Server] Listening on UDP:\(ERDConstants.udpPort)")

            // 3. Set up handlers BEFORE advertising/signaling so incoming connections are handled
            tcpChannel.onConnect = { [weak self] in
                ERDLog.info("[Server] Client connected!")
                Task { await self?.startStreaming() }
            }
            tcpChannel.onDisconnect = { [weak self] in
                ERDLog.info("[Server] Client disconnected")
                Task { await self?.stopStreaming() }
            }
            tcpChannel.onReceive = { [weak self] data in
                guard let self = self else { return }
                guard data.count >= ERDConstants.packetHeaderSize else { return }
                guard let header = PacketHeader.deserialize(from: data) else {
                    return
                }
                let payload = data.subdata(in: ERDConstants.packetHeaderSize..<data.count)

                switch header.type {
                case .inputEvent:
                    let receiver = self.stateQueue.sync { self.inputReceiver }
                    receiver?.handleInputEvent(payload)
                case .control:
                    if let msg = ControlMessage.deserialize(from: payload) {
                        switch msg.type {
                        case .requestKeyFrame:
                            let encoder = self.stateQueue.sync { self.videoEncoder }
                            encoder?.forceKeyFrame()
                        case .startStream: Task { await self.startStreaming() }
                        case .stopStream: Task { await self.stopStreaming() }
                        case .disconnect: Task { await self.stop() }
                        case .ping: break
                        case .streamConfigRequest:
                            if let data = msg.payload,
                               let req = StreamConfigurationRequestPayload.deserialize(from: data) {
                                Task { await self.handleStreamConfigRequest(req) }
                            }
                        case .streamConfigResponse, .streamConfigReject, .streamConfigError:
                            break // Server doesn't process these
                        case .clipboardSyncRequest:
                            break // Clipboard start/stop handled at session level
                        case .clipboardSyncUpdate:
                            if let data = msg.payload,
                               let update = ClipboardSyncUpdatePayload.deserialize(from: data) {
                                self.handleClipboardUpdate(update)
                            }
                        case .clipboardSyncError:
                            if let data = msg.payload,
                               let err = ClipboardSyncErrorPayload.deserialize(from: data) {
                                ERDLog.warning("[Server] Clipboard sync error from client: \(err.message)")
                            }
                        case .pong:
                            self.pongLock.lock()
                            self.lastPongTime = Date()
                            self.pongLock.unlock()
                        case .bitrateAdjust:
                            if let data = msg.payload,
                               let adj = BitrateAdjustPayload.deserialize(from: data) {
                                let newBitrate = Int(adj.targetBitrate)
                                ERDLog.info("[Server] Bitrate adjust request: \(newBitrate)")
                                let encoder = self.stateQueue.sync { self.videoEncoder }
                                encoder?.updateBitrate(newBitrate)
                            }
                        }
                    }
                case .handshake:
                    if let hs = HandshakePayload.deserialize(from: payload) {
                        ERDLog.info("[Server] Received handshake from client: \(hs.hostname) caps=\(hs.capabilities.rawValue)")
                        self.stateQueue.sync { self.peerCapabilities = hs.capabilities }
                        if self.isStreaming.value {
                            self.startClipboardSync()
                        }
                    }
                default: break
                }
            }

            // 4. Advertise via Bonjour (handlers are ready for incoming connections)
            tcpChannel.advertiseService(name: hostname)
            ERDLog.info("[Server] Advertising as '\(hostname)' via Bonjour")

            // 5. If PIN provided, exchange candidates via signaling
            if let pin = pin {
                await startSignaling(pin: pin)
            }

            ERDLog.info("[Server] Waiting for client connection...")
        } catch {
            isRunning = false
            onRunningChanged?(false)
            ERDLog.error("[Server] Fatal error: \(error)")
        }
    }

    private func startSignaling(pin: String) async {
        do {
            let stun = STUNClient()
            let (publicIP, publicPort) = try await stun.fetchPublicIP()
            ERDLog.info("[Server] STUN Public IP: \(publicIP):\(publicPort)")

            let localIP = NetworkUtils.getLocalIP() ?? "127.0.0.1"
            let signaling = SignalingClient(pin: pin, role: "server")
            let ourCandidate = SessionCandidate(role: "server", localIP: localIP, localPort: ERDConstants.tcpPort,
                                                  publicIP: publicIP, publicPort: publicPort)

            ERDLog.info("[Server] Exchanging candidates via PIN: \(pin)")
            let _ = try await signaling.exchangeCandidate(ourCandidate)
            signaling.stop()
            ERDLog.info("[Server] Signaling complete, waiting for client TCP connection...")
        } catch {
            ERDLog.error("[Server] Signaling failed: \(error)")
        }
    }

    private func startStreaming() async {
        guard !isStreaming.value else {
            return
        }

        guard CGPreflightScreenCaptureAccess() else {
            ERDLog.warning("[Server] Screen Recording permission not granted")
            ERDLog.warning("[Server]    Go to System Settings > Privacy & Security > Screen Recording")
            return
        }

        isStreaming.value = true

        let info = screenCapture.getDisplayInfo()
        let initialConfiguration = StreamConfiguration(
            width: UInt32(info.pixelWidth),
            height: UInt32(info.pixelHeight),
            bitrate: UInt32(ERDConstants.defaultBitrate),
            framesPerSecond: UInt16(ERDConstants.defaultFPS)
        )

        stateQueue.sync {
            inputReceiver = InputReceiver(screenWidth: CGFloat(info.width), screenHeight: CGFloat(info.height))
            frameSender = FrameSender(udpChannel: udpChannel)
            activeStreamConfig = initialConfiguration
        }

        // Send handshake to client (logical resolution for coordinate mapping)
        let handshake = HandshakePayload(hostname: hostname, screenWidth: UInt16(info.width),
                                          screenHeight: UInt16(info.height), scaleFactor: Float(info.scale),
                                          capabilities: [.streamConfiguration, .textClipboardSync])
        let header = PacketHeader(type: .handshakeAck, sequence: 0, timestamp: 0)
        var packet = header.serialize()
        packet.append(handshake.serialize())
        tcpChannel.send(packet)

        let preferredFPS = UserDefaults.standard.integer(forKey: "preferredFPS")
        let fps = preferredFPS > 0 ? preferredFPS : ERDConstants.defaultFPS

        // Setup pipeline: capture → encode → send (physical resolution for encoding)
        let encoder = makeVideoEncoder(
            width: info.pixelWidth,
            height: info.pixelHeight,
            bitrate: ERDConstants.defaultBitrate,
            fps: fps
        )

        stateQueue.sync { videoEncoder = encoder }

        screenCapture.onFrame = { [weak self] sampleBuffer in
            guard let self = self else { return }
            let encoder = self.stateQueue.sync { self.videoEncoder }
            encoder?.encode(sampleBuffer)
        }
        screenCapture.onCursorPosition = { [weak self] point in
            guard let self = self else { return }
            let nx = Float(point.x) / Float(info.width)
            let ny = Float(point.y) / Float(info.height)
            let sender = self.stateQueue.sync { self.frameSender }
            sender?.sendCursorUpdate(x: nx, y: ny)
        }
        screenCapture.onAudio = { [weak self] sampleBuffer in
            self?.handleAudioFrame(sampleBuffer)
        }

        do {
            try encoder.start()
            try await screenCapture.start(fps: fps)
            startHeartbeat()
            startClipboardSync()
            ERDLog.info("[Server] Streaming started: \(info.width)x\(info.height)")
        } catch {
            isStreaming.value = false
            stopHeartbeat()
            do { try await screenCapture.stop() } catch { }
            stateQueue.sync {
                videoEncoder?.stop()
                videoEncoder = nil
                frameSender = nil
                inputReceiver = nil
                activeStreamConfig = nil
            }
            ERDLog.error("[Server] Failed to start streaming: \(error)")
        }
    }

    private func stopStreaming() async {
        guard isStreaming.value else { return }
        isStreaming.value = false
        stopClipboardSync()
        stopHeartbeat()
        do { try await screenCapture.stop() } catch { ERDLog.error("[Server] Error stopping capture: \(error)") }

        stateQueue.sync {
            videoEncoder?.stop()
            videoEncoder = nil
            frameSender = nil
            inputReceiver = nil
            activeStreamConfig = nil
        }
        ERDLog.info("[Server] Streaming stopped")
    }

    public func stop() async {
        await stopStreaming()
        tcpChannel.stop()
        udpChannel.stop()
        isRunning = false
        onRunningChanged?(false)
    }

    // MARK: - Stream Configuration

    private func handleStreamConfigRequest(_ request: StreamConfigurationRequestPayload) async {
        let desired = request.desiredConfiguration

        // Validate requested dimensions
        let info = screenCapture.getDisplayInfo()
        let maxW = UInt32(info.pixelWidth)
        let maxH = UInt32(info.pixelHeight)

        if desired.width > maxW || desired.height > maxH || desired.width == 0 || desired.height == 0 {
            let reject = StreamConfigurationRejectPayload(
                requestID: request.requestID,
                reason: .unsupportedDimensions,
                message: "Dimensions must be 1..\(maxW)x\(maxH)")
            let msg = ControlMessage(type: .streamConfigReject, payload: reject.serialize())
            tcpChannel.sendControl(msg)
            return
        }

        if desired.framesPerSecond == 0 || desired.framesPerSecond > 120 {
            let reject = StreamConfigurationRejectPayload(
                requestID: request.requestID,
                reason: .unsupportedFPS,
                message: "FPS must be 1..120")
            let msg = ControlMessage(type: .streamConfigReject, payload: reject.serialize())
            tcpChannel.sendControl(msg)
            return
        }

        let clampedBitrate = max(UInt32(ERDConstants.minBitrate), min(desired.bitrate, UInt32(ERDConstants.maxBitrate)))

        let currentConfiguration = stateQueue.sync { self.activeStreamConfig }
        let captureDimensionsChanged = currentConfiguration.map {
            Int($0.width) != Int(desired.width) || Int($0.height) != Int(desired.height)
        } ?? true

        if captureDimensionsChanged {
            let encoder = makeVideoEncoder(
                width: Int(desired.width),
                height: Int(desired.height),
                bitrate: Int(clampedBitrate),
                fps: Int(desired.framesPerSecond)
            )

            do {
                try encoder.start()
            } catch {
                encoder.stop()
                let errPayload = StreamConfigurationErrorPayload(
                    requestID: request.requestID,
                    errorCode: .invalidRequest,
                    message: "Failed to restart encoder: \(error.localizedDescription)")
                let msg = ControlMessage(type: .streamConfigError, payload: errPayload.serialize())
                tcpChannel.sendControl(msg)
                return
            }

            let oldEncoder = stateQueue.sync { () -> VideoEncoder? in
                let encoder = self.videoEncoder
                self.videoEncoder = nil
                return encoder
            }

            do {
                try await screenCapture.updateConfiguration(
                    width: Int(desired.width),
                    height: Int(desired.height),
                    fps: Int(desired.framesPerSecond)
                )
            } catch {
                encoder.stop()
                stateQueue.sync { self.videoEncoder = oldEncoder }
                let errPayload = StreamConfigurationErrorPayload(
                    requestID: request.requestID,
                    errorCode: .invalidRequest,
                    message: "Failed to update capture: \(error.localizedDescription)")
                let msg = ControlMessage(type: .streamConfigError, payload: errPayload.serialize())
                tcpChannel.sendControl(msg)
                return
            }

            stateQueue.sync { self.videoEncoder = encoder }
            oldEncoder?.stop()
        } else {
            do {
                try await screenCapture.updateConfiguration(
                    width: Int(desired.width),
                    height: Int(desired.height),
                    fps: Int(desired.framesPerSecond)
                )
            } catch {
                let errPayload = StreamConfigurationErrorPayload(
                    requestID: request.requestID,
                    errorCode: .invalidRequest,
                    message: "Failed to update capture: \(error.localizedDescription)")
                let msg = ControlMessage(type: .streamConfigError, payload: errPayload.serialize())
                tcpChannel.sendControl(msg)
                return
            }

            let encoder = stateQueue.sync { self.videoEncoder }
            encoder?.updateBitrate(Int(clampedBitrate))
            encoder?.updateFPS(Int(desired.framesPerSecond))
        }

        let applied = StreamConfiguration(
            width: desired.width,
            height: desired.height,
            bitrate: clampedBitrate,
            framesPerSecond: desired.framesPerSecond)
        stateQueue.sync { activeStreamConfig = applied }

        let response = StreamConfigurationResponsePayload(requestID: request.requestID, activeConfiguration: applied)
        let msg = ControlMessage(type: .streamConfigResponse, payload: response.serialize())
        tcpChannel.sendControl(msg)
        ERDLog.info("[Server] Stream config applied: \(applied.width)x\(applied.height) @\(applied.framesPerSecond)fps \(applied.bitrate)bps")
    }

    private func makeVideoEncoder(width: Int, height: Int, bitrate: Int, fps: Int) -> VideoEncoder {
        let encoder = VideoEncoder(width: width, height: height, bitrate: bitrate, fps: fps)
        encoder.onEncodedFrame = { [weak self] data, isKeyFrame in
            guard let self = self else { return }
            let sender = self.stateQueue.sync { self.frameSender }
            let activeConfiguration = self.stateQueue.sync { self.activeStreamConfig }
            let width = Int(activeConfiguration?.width ?? UInt32(width))
            let height = Int(activeConfiguration?.height ?? UInt32(height))
            sender?.sendFrame(data: data, width: width, height: height, isKeyFrame: isKeyFrame)
        }
        return encoder
    }

    // MARK: - Clipboard Sync

    private func startClipboardSync() {
        let existingMonitor = stateQueue.sync { self.clipboardMonitor }
        guard existingMonitor == nil else {
            return
        }

        let peerCaps = stateQueue.sync { self.peerCapabilities }
        guard peerCaps.contains(.textClipboardSync) else {
            ERDLog.info("[Server] Peer does not support clipboard sync, skipping")
            return
        }

        let monitor = ClipboardMonitor { [weak self] text in
            guard let self = self else { return }
            let update = ClipboardSyncUpdatePayload(
                requestID: 0,
                direction: .hostToClient,
                origin: .localPasteboard,
                text: text)
            if let data = update.serialize() {
                let msg = ControlMessage(type: .clipboardSyncUpdate, payload: data)
                self.tcpChannel.sendControl(msg)
            }
        }
        stateQueue.sync { self.clipboardMonitor = monitor }
        monitor.start()
        ERDLog.info("[Server] Clipboard sync started")
    }

    private func stopClipboardSync() {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.stop()
        stateQueue.sync { self.clipboardMonitor = nil }
    }

    private func handleClipboardUpdate(_ update: ClipboardSyncUpdatePayload) {
        let monitor = stateQueue.sync { self.clipboardMonitor }
        monitor?.applyRemoteText(update.text)
        ERDLog.info("[Server] Clipboard received from client (\(update.text.count) chars)")
    }

    // MARK: - Heartbeat

    private func startHeartbeat() {
        stopHeartbeat()
        pongLock.lock()
        lastPongTime = Date()
        pongLock.unlock()

        let timer = DispatchSource.makeTimerSource(queue: heartbeatQueue)
        timer.schedule(deadline: .now() + ERDConstants.heartbeatInterval,
                       repeating: ERDConstants.heartbeatInterval)
        timer.setEventHandler { [weak self] in
            guard let self = self, self.isStreaming.value else { return }

            self.tcpChannel.sendControl(ControlMessage(type: .ping))

            self.pongLock.lock()
            let elapsed = Date().timeIntervalSince(self.lastPongTime)
            self.pongLock.unlock()

            if elapsed > ERDConstants.heartbeatInterval * 3 {
                ERDLog.warning("[Server] Client heartbeat timeout (\(elapsed)s)")
                Task { await self.stopStreaming() }
                self.tcpChannel.disconnectConnection()
            }
        }
        timer.resume()
        heartbeatTimer = timer
        ERDLog.info("[Server] Heartbeat started")
    }

    private func stopHeartbeat() {
        heartbeatTimer?.cancel()
        heartbeatTimer = nil
    }

    private func handleAudioFrame(_ sampleBuffer: CMSampleBuffer) {
        guard isStreaming.value else { return }
        guard let blockBuffer = CMSampleBufferGetDataBuffer(sampleBuffer) else { return }

        var length = 0
        var dataPointer: UnsafeMutablePointer<Int8>?
        let status = CMBlockBufferGetDataPointer(blockBuffer, atOffset: 0, lengthAtOffsetOut: nil, totalLengthOut: &length, dataPointerOut: &dataPointer)

        guard status == noErr, let pointer = dataPointer, length > 0 else { return }

        let audioData = Data(bytes: pointer, count: length)

        // Send audioFrame packet over UDP for ultra-low latency system audio
        udpChannel.sendPacket(type: .audioFrame, payload: audioData)
    }
}

import Foundation
import AppKit

/// Monitors the system pasteboard for text changes and provides loop prevention
/// for bidirectional clipboard sync between host and client.
///
/// Loop prevention strategy:
/// - Tracks `changeCount` to detect local pasteboard changes
/// - When applying remote text, records the resulting changeCount to suppress the echo
/// - Uses content hash dedup to avoid sending identical text back
public class ClipboardMonitor {
    private let pasteboard = NSPasteboard.general
    private var pollTimer: DispatchSourceTimer?
    private let pollQueue = DispatchQueue(label: "eclipticrd.clipboard.poll")
    private let lock = NSLock()

    /// The changeCount after our last write, used to suppress echo
    private var lastWrittenChangeCount: Int = -1
    /// Hash of the last text we sent or applied, for content-level dedup
    private var lastTextHash: Int = 0
    /// Whether monitoring is active
    private var isRunning = false
    /// Last observed changeCount
    private var lastChangeCount: Int = 0

    private let onLocalChange: (String) -> Void

    /// - Parameter onLocalChange: Called when the local pasteboard text changes
    ///   (excluding changes applied via `applyRemoteText`).
    public init(onLocalChange: @escaping (String) -> Void) {
        self.onLocalChange = onLocalChange
    }

    public func start() {
        lock.lock()
        guard !isRunning else { lock.unlock(); return }
        isRunning = true
        lastChangeCount = pasteboard.changeCount
        lastWrittenChangeCount = -1
        lastTextHash = 0
        lock.unlock()

        let timer = DispatchSource.makeTimerSource(queue: pollQueue)
        timer.schedule(deadline: .now() + 0.5, repeating: 0.5)
        timer.setEventHandler { [weak self] in
            self?.poll()
        }
        timer.resume()
        pollTimer = timer
    }

    public func stop() {
        lock.lock()
        isRunning = false
        lock.unlock()
        pollTimer?.cancel()
        pollTimer = nil
    }

    /// Apply text received from the remote peer to the local pasteboard.
    /// The resulting changeCount is recorded so the next poll won't echo it back.
    public func applyRemoteText(_ text: String) {
        let hash = text.hashValue
        lock.lock()
        lastTextHash = hash
        lock.unlock()

        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)

        lock.lock()
        lastWrittenChangeCount = pasteboard.changeCount
        lastChangeCount = pasteboard.changeCount
        lock.unlock()
    }

    private func poll() {
        let currentCount = pasteboard.changeCount

        lock.lock()
        let running = isRunning
        let prevCount = lastChangeCount
        let writtenCount = lastWrittenChangeCount
        let prevHash = lastTextHash
        lock.unlock()

        guard running, currentCount != prevCount else { return }

        // Suppress echo: if this changeCount matches what we just wrote, skip
        if currentCount == writtenCount {
            lock.lock()
            lastChangeCount = currentCount
            lock.unlock()
            return
        }

        lock.lock()
        lastChangeCount = currentCount
        lock.unlock()

        guard let text = pasteboard.string(forType: .string), !text.isEmpty else { return }

        // Content-level dedup: don't send if identical to last sent/applied text
        let hash = text.hashValue
        guard hash != prevHash else { return }

        // Check size limit
        guard let textData = text.data(using: .utf8),
              textData.count <= ERDConstants.maxClipboardTextBytes else { return }

        lock.lock()
        lastTextHash = hash
        lock.unlock()

        onLocalChange(text)
    }
}

import SwiftUI
import MetalKit
import AppKit

struct RemoteDesktopView: View {
    @EnvironmentObject var connectionManager: ConnectionManager
    @State private var showStats = false
    @State private var controlsExpanded = false
    @State private var titleBarInset: CGFloat = 0
    @State private var sessionWindow: NSWindow?

    var body: some View {
        GeometryReader { proxy in
            ZStack {
                MetalViewRepresentable()
                    .ignoresSafeArea()

                WindowChromeInsetReader(topInset: $titleBarInset)
                    .frame(width: 0, height: 0)
                    .allowsHitTesting(false)

                SessionWindowReader(
                    window: $sessionWindow,
                    onFullscreenChanged: { isFullscreen in
                        connectionManager.updateFullscreenState(isFullscreen)
                        if !isFullscreen {
                            restoreWindowPresentationIfNeeded()
                        }
                    }
                )
                    .frame(width: 0, height: 0)
                    .allowsHitTesting(false)

                // Top-Right Panel: Session Controls
                VStack(alignment: .trailing) {
                    SessionControlsView(
                        serverName: connectionManager.serverName ?? "Remote Session",
                        sessionControls: connectionManager.sessionControls,
                        showStats: $showStats,
                        isExpanded: $controlsExpanded,
                        toggleImmersiveMode: toggleImmersiveMode,
                        selectQuality: { preset in
                            connectionManager.requestStreamConfiguration(quality: preset)
                        },
                        selectResolution: { preset in
                            connectionManager.requestStreamConfiguration(resolution: preset)
                        }
                    ) {
                        connectionManager.disconnect()
                    }
                }
                .padding(.top, overlayTopInset(safeAreaTop: proxy.safeAreaInsets.top))
                .padding(.trailing, ERDTheme.Spacing.card)
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topTrailing)

                // Bottom-Left Panel: Session Telemetry HUD
                if showStats {
                    StatsOverlayView()
                        .frame(maxWidth: ERDTheme.Layout.dashboardSidebarWidth, alignment: .leading)
                        .transition(.move(edge: .bottom).combined(with: .opacity))
                        .padding(.bottom, overlayBottomInset(safeAreaBottom: proxy.safeAreaInsets.bottom))
                        .padding(.leading, ERDTheme.Spacing.card)
                        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottomLeading)
                }

                // Floating Clipboard Sync Toast
                if connectionManager.showClipboardToast {
                    VStack {
                        HStack(spacing: ERDTheme.Spacing.small) {
                            Image(systemName: "doc.on.clipboard.fill")
                                .font(ERDTheme.Typography.detailMedium)
                                .foregroundStyle(ERDTheme.green)

                            Text(connectionManager.clipboardToastText)
                                .font(ERDTheme.Typography.detailMedium)
                                .foregroundStyle(ERDTheme.strongText)
                        }
                        .padding(.horizontal, ERDTheme.Spacing.section)
                        .padding(.vertical, ERDTheme.Spacing.small)
                        .erdCardBackground(
                            .surface(
                                fill: ERDTheme.elevatedSurface.opacity(0.96),
                                stroke: ERDTheme.green.opacity(0.38),
                                cornerRadius: ERDTheme.Radius.panel
                            )
                        )
                        .transition(.move(edge: .top).combined(with: .opacity))
                        .padding(.top, overlayTopInset(safeAreaTop: proxy.safeAreaInsets.top))

                        Spacer()
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
                    .allowsHitTesting(false)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .animation(.spring(response: 0.24, dampingFraction: 0.88), value: controlsExpanded)
        .animation(.easeInOut(duration: 0.18), value: showStats)
        .preferredColorScheme(.dark)
        .onAppear {
            KeyboardShortcutMonitor.shared.register { showStats.toggle() }
        }
        .onDisappear {
            KeyboardShortcutMonitor.shared.unregister()
            restoreWindowPresentationIfNeeded()
        }
    }

    private func overlayTopInset(safeAreaTop: CGFloat) -> CGFloat {
        max(
            ERDTheme.Spacing.card,
            safeAreaTop + ERDTheme.Spacing.small,
            titleBarInset + ERDTheme.Spacing.small
        )
    }

    private func overlayBottomInset(safeAreaBottom: CGFloat) -> CGFloat {
        max(
            ERDTheme.Spacing.card,
            safeAreaBottom + ERDTheme.Spacing.small
        )
    }

    private func toggleImmersiveMode() {
        guard let window = sessionWindow else { return }

        let shouldEnable = !connectionManager.sessionControls.isImmersiveModeEnabled || !connectionManager.sessionControls.isFullscreen
        connectionManager.setImmersiveModeEnabled(shouldEnable)
        window.collectionBehavior.insert(.fullScreenPrimary)

        if shouldEnable {
            window.titleVisibility = .hidden
            window.titlebarAppearsTransparent = true
            NSApplication.shared.presentationOptions = [.autoHideToolbar, .autoHideMenuBar, .fullScreen]
            if !window.styleMask.contains(.fullScreen) {
                window.toggleFullScreen(nil)
            }
        } else {
            restoreWindowPresentation(window: window)
            if window.styleMask.contains(.fullScreen) {
                window.toggleFullScreen(nil)
            }
        }
    }

    private func restoreWindowPresentationIfNeeded() {
        guard let window = sessionWindow else { return }
        restoreWindowPresentation(window: window)

        if window.styleMask.contains(.fullScreen) {
            window.toggleFullScreen(nil)
        }
    }

    private func restoreWindowPresentation(window: NSWindow) {
        NSApplication.shared.presentationOptions = []
        window.titleVisibility = .visible
        window.titlebarAppearsTransparent = false
    }
}

