        let mtkView = TrackingMTKView()
        mtkView.device = MTLCreateSystemDefaultDevice()
        mtkView.preferredFramesPerSecond = ERDConstants.defaultFPS
        mtkView.enableSetNeedsDisplay = false
        mtkView.isPaused = false
